// Where the CV's files are and what each holds (docs/CV.md). Pure: the registry the save, the sync, the build
// and the drift check share, so none of them names a file the others do not.

/** The repository directory the CV lives in, one markdown file per section plus the profile. */
export const CV_DIR = "content/cv";

/**
 * The files, in the order their entries make the CV's flat list (traditional CV order, which is also the
 * page's "by type" sort). `type` is the entry type a section file holds; the profile holds none.
 *
 * @type {ReadonlyArray<{ slug: string, type: import("./types.ts").CvType | "profile" }>}
 */
export const CV_FILES = [
  { slug: "profile", type: "profile" },
  { slug: "appointments", type: "appointment" },
  { slug: "education", type: "education" },
  { slug: "publications", type: "publication" },
  { slug: "grants", type: "grant" },
  { slug: "honors", type: "award" },
  { slug: "talks", type: "talk" },
  { slug: "courses", type: "course" },
  { slug: "mentoring", type: "mentoring" },
  { slug: "service", type: "service" },
  { slug: "development", type: "development" },
];

/** @param {string} slug */
export function cvSourcePath(slug) {
  return `${CV_DIR}/${slug}.md`;
}

/**
 * The file a slug names, or undefined. A save cannot create a file: the set of files is structure, so a
 * new one is a change to CV_FILES and to the code that reads it.
 *
 * @param {string} slug
 */
export function cvFileFor(slug) {
  return CV_FILES.find((file) => file.slug === slug);
}

app/lib/dictionary-entries.mjs.source:
/**
 * How a dictionary entry reads on each surface. The entries themselves are files, content/dictionary/<key>.md
 * (docs/DICTIONARY.md), compiled by app/lib/dictionary/compile.mjs and drawn from D1 (the dictionary_entries
 * table) at request time; this module only turns one entry into the page's lead, the markdown twin's lead, the
 * search record's sentences and the DefinedTerm JSON-LD, so people and machines read the same entry.
 *
 * Each name is a real English word most readers rarely meet, so the page first says what the word means, then
 * what the software is. Sense 1 follows the dictionaries; sense 2 is the software, plain and factual, and
 * carries the subject label "software." in italics, as a dictionary marks a specialised sense.
 */

/**
 * An etymology is text with foreign words marked, so the page can set them in italics with their
 * language and the twin can emphasise them: a string is plain text, a pair is [lang, word].
 *
 * @typedef {string | [string, string]} EtymologyPart
 * @typedef {{
 *   path: string,
 *   term: string,
 *   syllables: string,
 *   ipa: string,
 *   respelling: string,
 *   partOfSpeech: string,
 *   plural: string[] | null,
 *   etymology: EtymologyPart[],
 *   senses: [string, string],
 *   senseLabels: [string | null, string | null],
 *   audio: string,
 * }} DictionaryEntry
 */

/** The subject label on each software sense (Dustin, 2026-09-28), set in italics before it. */
export const SOFTWARE_LABEL = "software";

/** @param {string | null | undefined} label */
function labelPrefix(label) {
  return label ? `${label}. ` : "";
}

/** @param {string} term */
export function listenLabel(term) {
  return `Listen to the pronunciation of ${term}`;
}

/** @param {DictionaryEntry} entry */
export function etymologyText(entry) {
  return entry.etymology.map((part) => (typeof part === "string" ? part : part[1])).join("");
}

/**
 * The entry as plain sentences, for the search record, where markup would be noise.
 *
 * @param {DictionaryEntry} entry
 */
export function dictionaryEntryText(entry) {
  const plural = entry.plural ? `; plural ${entry.plural.join(" or ")}` : "";
  return [
    `${entry.term} (${entry.syllables}), ${entry.ipa}, ${entry.respelling}, ${entry.partOfSpeech}${plural}.`,
    ...entry.senses.map((sense, i) => `${i + 1}. ${labelPrefix(entry.senseLabels[i])}${sense}`),
    `Etymology: ${etymologyText(entry)}`,
  ].join(" ");
}

/**
 * The entry in the markdown twin, directly under the title, the same place the page shows it.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin absolute origin for the audio link, so the twin read alone still resolves
 */
export function dictionaryEntryMarkdown(entry, origin = "") {
  const plural = entry.plural ? `; plural ${entry.plural.map((form) => `*${form}*`).join(" or ")}` : "";
  const etymology = entry.etymology.map((part) => (typeof part === "string" ? part : `*${part[1]}*`)).join("");
  return [
    `**${entry.syllables}** ${entry.ipa} (${entry.respelling}), *${entry.partOfSpeech}*${plural}. [Pronunciation audio](${origin}${entry.audio})`,
    "",
    ...entry.senses.map((sense, i) => {
      const label = entry.senseLabels[i];
      return `${i + 1}. ${label ? `*${label}.* ` : ""}${sense}`;
    }),
    "",
    `Etymology: ${etymology}`,
    "",
  ].join("\n");
}

/**
 * schema.org DefinedTerm: the name, sense 2 as the description (what the word means on this page),
 * and the set every entry belongs to, which is the Software hub.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin
 */
export function definedTermJsonLd(entry, origin) {
  return {
    "@context": "https://schema.org",
    "@type": "DefinedTerm",
    name: entry.term,
    description: entry.senses[1],
    url: `${origin}${entry.path}`,
    inDefinedTermSet: {
      "@type": "DefinedTermSet",
      name: "Software names on dustinedwards.info",
      url: `${origin}/software`,
    },
  };
}

app/lib/editor/publish-policy.mjs.source:
import matter from "gray-matter";

/**
 * @typedef {{ kind: "admin" } | { kind: "operator", id: string } | { kind: "smoke", id: string } | { kind: "carrel", changeId: string }} Actor
 */

export const SMOKE_READ_ONLY_POLICY = "smoke-is-read-only";

/**
 * Keyed by kind, so a new actor kind is a typecheck failure rather than a silent permission (a
 * switch with a missing case compiles and falls through).
 *
 * @type {Readonly<Record<Actor["kind"], Readonly<{ write: boolean, firstPublish: boolean, destroy: boolean }>>>}
 */
export const WRITE_CAPABILITIES = {
  admin: { write: true, firstPublish: true, destroy: true },
  operator: { write: true, firstPublish: false, destroy: false },
  /**
   * Carrel's key, through /api/carrel/v1 only. It may publish for the first time (Carrel design
   * decision 2: Carrel decides who triggers it) and may delete a post since site-api v0.3.0, which asks for
   * it (DELETE /content/:id). Carrel's own rules decide who may ask; the site still checks the version.
   */
  carrel: { write: true, firstPublish: true, destroy: true },
  /**
   * Every capability false; check:policy asserts it. Read-only is not safe: it still sees drafts and
   * the operator email (not stubbed, since the topbar's narrow-width measurement depends on it).
   */
  smoke: { write: false, firstPublish: false, destroy: false },
};

export class PolicyError extends Error {
  /**
   * @param {string} message
   * @param {string} policy
   */
  constructor(message, policy) {
    super(message);
    this.name = "PolicyError";
    /** @type {string} */
    this.policy = policy;
  }
}

/** @returns {string} */
function today() {
  return new Date().toISOString().slice(0, 10);
}

/**
 * @param {string} raw
 * @returns {{ draft: boolean, firstPublished: string | null }}
 */
export function readState(raw) {
  const data = /** @type {Record<string, unknown>} */ (matter(raw).data);
  const value = data.first_published;
  const firstPublished =
    value instanceof Date
      ? value.toISOString().slice(0, 10)
      : typeof value === "string" && value.trim()
        ? value.trim()
        : null;
  return { draft: data.draft === true, firstPublished };
}

/**
 * gray-matter turns an unquoted 2026-07-30 into a Date while the stamp writes a string, so both sides
 * reduce a date to its ISO day before comparing.
 *
 * @param {Record<string, unknown>} data
 * @returns {string}
 */
function comparableFrontmatter(data) {
  /** @type {Record<string, unknown>} */
  const flat = {};
  for (const key of Object.keys(data).sort()) {
    const value = data[key];
    flat[key] = value instanceof Date ? value.toISOString().slice(0, 10) : value;
  }
  return JSON.stringify(flat);
}

/**
 * Overwrites, and that is the security part: the value must come from the committed file, or an agent
 * could publish a draft by submitting first_published itself. The line edit keeps the diff to one
 * field; it is parsed back and kept only if exact, since a quoted key or a list value defeats it.
 *
 * @param {string} raw
 * @param {string | null} value
 * @returns {string}
 */
export function forceFirstPublished(raw, value) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(raw);
  if (!match) return raw;

  const block = match[1];
  if (block === undefined) return raw;
  const rest = raw.slice(match[0].length);
  const kept = block
    .split("\n")
    .filter((line) => !/^first_published\s*:/.test(line));

  if (value) kept.push(`first_published: ${value}`);

  const edited = `---\n${kept.join("\n")}\n---\n${rest}`;

  const before = matter(raw);
  const want = { .../** @type {Record<string, unknown>} */ (before.data) };
  if (value) want.first_published = value;
  else delete want.first_published;

  try {
    const after = matter(edited);
    if (
      after.content === before.content &&
      comparableFrontmatter(/** @type {Record<string, unknown>} */ (after.data)) ===
        comparableFrontmatter(want)
    ) {
      return edited;
    }
  } catch {
    // YAML cannot read the edit. Fall through.
  }

  return matter.stringify(before.content, want);
}

/**
 * Computed here because only the prior file can tell a first publication from a republication.
 *
 * @typedef {"saved" | "published-first" | "republished" | "unpublished"} SaveOutcome
 */

/**
 * @param {{ wantsPublished: boolean, everPublished: boolean, priorDraft: boolean | null }} state
 * @returns {SaveOutcome}
 */
function classify(state) {
  if (state.wantsPublished) {
    if (!state.everPublished) return "published-first";
    return state.priorDraft === true ? "republished" : "saved";
  }
  return state.priorDraft === false ? "unpublished" : "saved";
}

/**
 * Operators may not delete: the destructive verb needs more authority than publishing, not less.
 * Throws rather than returning a boolean, so a caller that forgets to check cannot proceed.
 *
 * @param {{ actor: Actor }} options
 * @returns {void}
 * @throws {PolicyError} when the actor may not delete
 */
export function decideDelete(options) {
  const may = WRITE_CAPABILITIES[options.actor.kind];

  if (!may.write) {
    throw new PolicyError(
      "Refused: this credential is READ ONLY. It may render admin pages and it " +
        "may not change anything, delete included.",
      SMOKE_READ_ONLY_POLICY,
    );
  }

  if (!may.destroy) {
    throw new PolicyError(
      "Refused: deleting a post is reserved to the human admin. An operator " +
        "may create, edit, unpublish and republish a post, but not destroy it. " +
        "Unpublish it instead (draft: true), which is reversible, and ask " +
        "Dustin to delete it from /admin/posts if it should go for good.",
      "delete-requires-admin",
    );
  }
}

/**
 * @param {{ actor: Actor, incomingRaw: string, priorRaw: string | null }} options
 * @returns {{ raw: string, firstPublished: string | null, published: boolean, outcome: SaveOutcome }}
 */
export function decide(options) {
  const incoming = readState(options.incomingRaw);
  const prior = options.priorRaw ? readState(options.priorRaw) : null;

  // The prior FILE is the only authority, and the check is on the resulting state, not a diff.
  const priorFirstPublished = prior?.firstPublished ?? null;
  const wantsPublished = !incoming.draft;
  const everPublished = priorFirstPublished !== null;

  const may = WRITE_CAPABILITIES[options.actor.kind];

  if (!may.write) {
    throw new PolicyError(
      "Refused: this credential is READ ONLY. It may render admin pages and it " +
        "may not save a post, in any state, new or existing.",
      SMOKE_READ_ONLY_POLICY,
    );
  }

  if (!may.firstPublish && wantsPublished && !everPublished) {
    throw new PolicyError(
      "Refused: publishing a post for the first time is reserved to the human " +
        "admin. This post has never been public, so an operator cannot set " +
        "draft to false on it. Save it as a draft (draft: true) and ask Dustin " +
        "to publish it from /admin/posts. Once it has been published once, an " +
        "operator may unpublish and republish it freely.",
      "first-publish-requires-admin",
    );
  }

  const firstPublished =
    priorFirstPublished ?? (wantsPublished ? today() : null);

  return {
    raw: forceFirstPublished(options.incomingRaw, firstPublished),
    firstPublished,
    published: wantsPublished,
    outcome: classify({
      wantsPublished,
      everPublished,
      priorDraft: prior ? prior.draft : null,
    }),
  };
}

/**
 * The rule for a file kind whose only status is its own `draft` flag (procedures, publications): the
 * same policy as a post, read from the prior FILE. An actor without the write capability is refused, and
 * one without first-publish may unpublish and republish but never make something public that never was.
 *
 * @param {{ actor: Actor, noun: string, incomingDraft: boolean, priorRaw: string | null, isDraft: (raw: string) => boolean }} options
 *   `noun` is the thing saved ("procedure"), named in the refusal.
 */
export function decideFileWrite({ actor, noun, incomingDraft, priorRaw, isDraft }) {
  const may = WRITE_CAPABILITIES[actor.kind];
  if (!may.write) {
    throw new PolicyError(`Refused: this credential is READ ONLY and may not save a ${noun}.`, SMOKE_READ_ONLY_POLICY);
  }
  const everPublished = priorRaw !== null && !isDraft(priorRaw);
  if (!may.firstPublish && !incomingDraft && !everPublished) {
    throw new PolicyError(
      `Refused: publishing a ${noun} for the first time is reserved to the human admin. Save it with ` +
        "draft: true, and ask Dustin to publish it.",
      "first-publish-requires-admin",
    );
  }
}

