// Repairs only when EVERY failing check is a known drift class: an unknown one blocks all repair, since
// a compound failure may share a root cause. No token still fails the run: alert-only, never silence.

import { awaitAskConvergence } from "./ask-converge.mjs";

/** Only idempotent repairs through the operator API, since this runs unattended. Map order is repair order. */
export const REPAIRABLE = /** @type {const} */ ({
  // Content first: sync_ask reads search_docs, which sync_posts, sync_procedures, sync_dictionary,
  // sync_pages and sync_publications rewrite, so the reverse uploads a stale corpus.
  "content-drift": "sync_posts",
  "procedures-drift": "sync_procedures",
  // Before the pages: an entry write refreshes the page row it opens, and a page compile reads the entry from D1.
  "dictionary-drift": "sync_dictionary",
  // Beside the dictionary: the roster is drawn into the program page and the home page, which a page compile or a
  // purge may re-open, so it converges before the pages do. It writes no search record.
  "roster-drift": "sync_roster",
  // Before the pages as well: the phage page is compiled from the phage rows, so a page compile reads them from D1,
  // and a phage write refreshes the page row it is drawn into.
  "phage-drift": "sync_phages",
  // Beside the phages: nothing is drawn from a registry row into another store, so it converges on its own.
  "registry-drift": "sync_registry",
  "pages-drift": "sync_pages",
  "publications-drift": "sync_publications",
  // Reads nothing the Ask upload reads; listed with the file-derived stores.
  "llms-drift": "sync_llms",
  "cv-drift": "sync_cv",
  // After sync_cv, which it follows: the PDF is drawn from the rows sync_cv converges. It reads nothing the Ask
  // upload reads.
  "cv-pdf-drift": "sync_cv_pdf",
  "ask-index-drift": "sync_ask",
  "media-index-drift": "sync_media",
  // Order-independent. backup_media only copies and has no delete branch, which is why it may fire unattended.
  "media-backup-drift": "backup_media",
});

/**
 * @param {unknown} failingNames names of checks reporting ok:false
 * @param {{ hasToken: boolean }} options
 * @returns {{
 *   repair: string[],
 *   unknown: string[],
 *   alertOnly: boolean,
 *   reason: string,
 * }}
 */
export function repairPlan(failingNames, { hasToken }) {
  const names = Array.isArray(failingNames)
    ? failingNames.filter((n) => typeof n === "string" && n.length > 0)
    : [];

  if (names.length === 0) {
    return {
      repair: [],
      unknown: [],
      alertOnly: true,
      reason:
        "no failing check was named, so there is nothing to repair. A run that reports " +
        "unhealthy without naming a check is a fault in the endpoint, not a drift.",
    };
  }

  const unknown = names.filter((n) => !(n in REPAIRABLE));

  if (unknown.length > 0) {
    return {
      repair: [],
      unknown,
      alertOnly: true,
      reason:
        `no self-repair: ${unknown.join(", ")} ${unknown.length === 1 ? "is" : "are"} not a ` +
        `known drift class. Repair is not attempted for the recognized classes either, ` +
        `because a compound failure may share a root cause.`,
    };
  }

  if (!hasToken) {
    return {
      repair: [],
      unknown: [],
      alertOnly: true,
      reason:
        "no self-repair: OPERATOR_TOKEN is not set on this watcher, so the repair door " +
        "cannot be opened. The GitHub half takes it as a repository secret " +
        "(`gh secret set OPERATOR_TOKEN`); the watchdog Worker takes it as a wrangler " +
        "secret (`wrangler secret put OPERATOR_TOKEN -c wrangler.watchdog.jsonc`). " +
        "Alerting only.",
    };
  }

  // Ordered by the map and deduplicated, so one tool is never called twice and run logs compare.
  const tools = Object.keys(REPAIRABLE)
    .filter((name) => names.includes(name))
    .map((name) => REPAIRABLE[/** @type {keyof typeof REPAIRABLE} */ (name)]);

  return {
    repair: [...new Set(tools)],
    unknown: [],
    alertOnly: false,
    reason: `self-repair: ${names.join(", ")} -> ${[...new Set(tools)].join(", ")}`,
  };
}

/**
 * An unreadable body yields no names, so repairPlan alerts rather than writes. ok === false, not !ok,
 * so a check missing the field is not counted as failing.
 *
 * @param {unknown} body
 * @returns {string[]}
 */
export function failingCheckNames(body) {
  const checks = /** @type {any} */ (body)?.checks;
  if (!Array.isArray(checks)) return [];
  return checks
    .filter((c) => c && typeof c === "object" && c.ok === false && typeof c.name === "string")
    .map((c) => c.name);
}

// The recheck is in the action list: a repair's own 200 proves one index, the recheck proves the
// endpoint agrees, and a step living only in the caller is a step no test can name.

/**
 * @typedef {{ type: "repair", tool: string }} RepairAction
 * @typedef {{ type: "recheck" }} RecheckAction
 * @typedef {{ type: "notify", reason: string }} NotifyAction
 * @typedef {RepairAction | RecheckAction | NotifyAction} WatchdogAction
 */

/**
 * @typedef {{ status: number, body: unknown, error?: string }} HealthReading
 */

/**
 * A 200 whose body says `ok: true`; anything else, a 503 included, is unhealthy.
 *
 * @param {HealthReading | null | undefined} reading
 * @returns {boolean}
 */
function isHealthyReading(reading) {
  const body = reading?.body;
  return (
    Number(reading?.status) === 200 &&
    !!body &&
    typeof body === "object" &&
    /** @type {any} */ (body).ok === true
  );
}

/**
 * Anything but a healthy 200 takes the same path: a 503 is how this endpoint reports a failing check.
 *
 * @param {HealthReading} reading
 * @param {{ hasToken: boolean }} options
 * @returns {WatchdogAction[]}
 */
export function watchdogActions(reading, { hasToken }) {
  const status = Number(reading?.status);
  const body = reading?.body;

  if (isHealthyReading(reading)) return [];

  // A transport failure is reported with its cause: a timeout and a 1042 are different pages, and
  // without the cause the mail says "no failing check was named" about a fetch that never happened.
  if (status === 0) {
    const cause = typeof reading?.error === "string" && reading.error ? reading.error : "";
    return [
      {
        type: "notify",
        reason:
          `the health endpoint could not be reached at all${cause ? `: ${cause}` : `, and the ` +
            `reading carried no cause, which is itself a defect in the reader`}. Nothing was ` +
          `repaired, because a reading that never happened names no drift.`,
      },
    ];
  }

  const plan = repairPlan(failingCheckNames(body), { hasToken });

  if (plan.alertOnly) return [{ type: "notify", reason: plan.reason }];

  return [
    ...plan.repair.map((tool) => /** @type {RepairAction} */ ({ type: "repair", tool })),
    { type: "recheck" },
  ];
}

/**
 * A failed repair and a still-failing recheck are both reported, not just the first.
 *
 * @param {{ misses: string[], recheck: HealthReading | null }} outcome
 * @returns {WatchdogAction[]}
 */
export function watchdogOutcome({ misses, recheck }) {
  const failed = Array.isArray(misses) ? misses.filter((m) => typeof m === "string" && m) : [];

  const reasons = [];
  if (failed.length > 0) reasons.push(`self-repair FAILED: ${failed.join("; ")}. The drift stands.`);

  if (recheck === null || recheck === undefined) {
    reasons.push("the re-check did not complete, so the repair proved nothing.");
  } else {
    const stillFailing = failingWithCounts(recheck.body);
    if (!isHealthyReading(recheck)) {
      reasons.push(
        `self-repair ran and the endpoint is STILL unhealthy (HTTP ${recheck.status}` +
          `${stillFailing.length ? `, failing: ${stillFailing.join(", ")}` : ""}).`,
      );
    }
  }

  return reasons.length > 0 ? [{ type: "notify", reason: reasons.join(" ") }] : [];
}

/**
 * Each failing check by name, with the counts the public body carries for a failing drift check.
 *
 * @param {unknown} body
 * @returns {string[]}
 */
function failingWithCounts(body) {
  const checks = /** @type {any} */ (body)?.checks;
  if (!Array.isArray(checks)) return [];
  return checks
    .filter((c) => c && typeof c === "object" && c.ok === false && typeof c.name === "string")
    .map((c) =>
      typeof c.expected === "number" && typeof c.present === "number"
        ? `${c.name} (expected ${c.expected}, present ${c.present})`
        : c.name,
    );
}

/**
 * After the watchdog's own sync_ask, the Ask index can list short for up to about a minute: it is
 * eventually consistent, and a full re-upload is followed by a short count (157 then 155 in deploy
 * run 36274700184). So a re-check still failing only on that is re-read on ship's cadence and window
 * (awaitAskConvergence) before it can alert. The last full reading is returned, so another failing
 * check, or a count that never arrives, still alerts with its counts.
 *
 * @param {{
 *   recheck: HealthReading | null,
 *   attempted: string[],
 *   reread: () => Promise<HealthReading>,
 *   sleep: (ms: number) => Promise<unknown>,
 *   now?: () => number,
 * }} options
 * @returns {Promise<{ reading: HealthReading | null, polls: number }>}
 */
export async function settleAskRecheck({ recheck, attempted, reread, sleep, now }) {
  if (!recheck || !attempted.includes("sync_ask")) return { reading: recheck, polls: 0 };
  if (!failingCheckNames(recheck.body).includes("ask-index-drift")) return { reading: recheck, polls: 0 };

  let latest = recheck;
  const { polls } = await awaitAskConvergence({
    reading: async () => {
      const reading = await reread();
      // A reading that never arrived names no drift, so the last real one stands.
      if (Number(reading?.status) === 0) return null;
      latest = reading;
      const checks = /** @type {any} */ (reading.body)?.checks;
      return Array.isArray(checks) ? (checks.find((c) => c?.name === "ask-index-drift") ?? null) : null;
    },
    sleep,
    now,
  });
  return { reading: latest, polls };
}

/**
 * Reports the operator API's own error and detail, since a bare status discards the diagnosis. A 422
 * is unrepairable: resending the same corpus cannot correct it; usually the repo is ahead of the deploy.
 *
 * @param {string} tool the operator tool that was called
 * @param {number} status the HTTP status it answered
 * @param {unknown} payload the parsed response body, or null
 * @returns {{ miss: string, unrepairable: boolean }}
 */
export function refusalMiss(tool, status, payload) {
  const body = payload && typeof payload === "object" ? /** @type {any} */ (payload) : null;
  const said = typeof body?.error === "string" ? body.error.trim() : "";
  const field = typeof body?.detail?.field === "string" && body.detail.field ? body.detail.field : "";
  const line = typeof body?.detail?.line === "number" ? body.detail.line : null;

  return {
    miss:
      `${tool} answered ${status}` +
      (said ? `: ${said}` : "") +
      (field ? ` [field ${field}]` : "") +
      (line === null ? "" : ` [line ${line}]`),
    unrepairable: status === 422,
  };
}

app/lib/json-ld.mjs.source:
/**
 * `<script>` contents are raw text ended only by a literal `</script`, so a
 * value containing it would close the element early. U+2028/9 are escaped
 * because they are line terminators if this is ever read as JavaScript.
 * The escapes parse back to identical data, so they are safe on every emitter.
 */

// Built from strings: a literal U+2028 is invisible and does not survive a copy.
const LINE_SEPARATOR = new RegExp("\\u2028", "g");
const PARAGRAPH_SEPARATOR = new RegExp("\\u2029", "g");

/**
 * @param {unknown} value
 * @returns {string}
 */
export function jsonLd(value) {
  return (
    JSON.stringify(value)
      .replace(/</g, "\\u003c")
      .replace(/>/g, "\\u003e")
      .replace(/&/g, "\\u0026")
      .replace(LINE_SEPARATOR, "\\u2028")
      .replace(PARAGRAPH_SEPARATOR, "\\u2029")
  );
}

app/lib/media-ref-key.mjs.source:
/**
 * NUL cannot occur in any part, so the join is unambiguous; a printable `|`
 * would collide ("a|b","c" vs "a","b|c") and silently drop a ref. Keep it an
 * escape: a literal NUL makes the file binary to git and invisible in editors.
 *
 * @param {{ mediaKey: string, form: string, detail: string | null }} ref
 * @returns {string}
 */
export function mediaRefKey(ref) {
  return `${ref.mediaKey}\u0000${ref.form}\u0000${ref.detail ?? ""}`;
}

app/lib/media/tags.mjs.source:
// A column, not a join table like posts: media tags have no public page, and search stays one LIKE chain.
// Stored DELIMITER-WRAPPED (`,alpha,beta,`) so an exact match is `LIKE '%,art,%'` and misses `chart`;
// the empty list is "" so an untagged row cannot match `%,%`.

const TAG_DELIMITER = ",";

export const MAX_TAG_LENGTH = 32;

export const MAX_TAGS = 12;

/**
 * @param {unknown} raw
 * @returns {string}
 */
export function normaliseTag(raw) {
  if (typeof raw !== "string") return "";
  return raw
    .toLowerCase()
    .split(TAG_DELIMITER)
    .join(" ")
    .trim()
    .replace(/\s+/g, "-")
    // Never a `%` or `_`: they are LIKE wildcards and would turn a stored value into a pattern.
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_TAG_LENGTH)
    .replace(/-+$/, "");
}

/**
 * Sorted so the same set always stores the same bytes, whatever the typing order.
 *
 * @param {unknown} input
 * @returns {string[]}
 */
export function normaliseTags(input) {
  const parts = Array.isArray(input)
    ? input
    : typeof input === "string"
      ? input.split(TAG_DELIMITER)
      : [];
  const seen = new Set();
  for (const part of parts) {
    const tag = normaliseTag(part);
    if (tag) seen.add(tag);
  }
  return [...seen].sort().slice(0, MAX_TAGS);
}

/**
 * @param {unknown} input
 * @returns {string}
 */
export function serialiseTags(input) {
  const tags = normaliseTags(input);
  if (tags.length === 0) return "";
  return `${TAG_DELIMITER}${tags.join(TAG_DELIMITER)}${TAG_DELIMITER}`;
}

/**
 * @param {unknown} stored
 * @returns {string[]}
 */
export function parseTags(stored) {
  if (typeof stored !== "string" || stored === "") return [];
  return normaliseTags(stored);
}

/**
 * Null means "no filter", never a needle: `%,,%` would match every tagged row.
 *
 * @param {unknown} raw
 * @returns {string | null}
 */
export function exactTagNeedle(raw) {
  const tag = normaliseTag(raw);
  if (!tag) return null;
  return `%${TAG_DELIMITER}${tag}${TAG_DELIMITER}%`;
}

app/lib/pages/links.mjs.source:
// The internal links of a page, judged at save time. check:links is CI's full gate over every link the
// site publishes, built from the repository's sources; a save through the operator API is live before CI
// runs, so the part of that judgement a Worker can make from D1 and code is made here, with the same
// gateway functions the router uses (docs/PAGES.md).
//
// It refuses only what it can PROVE broken: a link into a namespace this module can list completely
// (the Research, Teaching, Software and recipe pages, the procedures, the posts) that names nothing in
// it, a path the gateway answers 410, a draft post, and an anchor missing from a content page. Any other
// address passes here and is left to check:links.

import { CONTENT_PAGE_PATHS, contentPageMarkdownPath } from "../content-pages.mjs";
import { movedPathTarget } from "../path-moves.mjs";
import { wordpressDisposition } from "../wordpress-redirects.mjs";

/**
 * @typedef {{
 *   procedurePaths: ReadonlySet<string>,
 *   posts: ReadonlyMap<string, boolean>,
 *   idsOf: (path: string) => ReadonlySet<string> | null,
 * }} AddressBook
 * `posts` maps `/writing/<slug>` to whether a reader can open it; `idsOf` is the element ids a content
 * page carries, or null for a path that is not one.
 */

const decodeEntities = (/** @type {string} */ value) =>
  value.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">");

const safeDecode = (/** @type {string} */ value) => {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

const SITE_HOST = /^https?:\/\/(?:www\.)?dustinedwards\.info(?=[/?#]|$)/i;

/** Every element id in rendered HTML. */
export function idsIn(/** @type {string} */ html) {
  return new Set([...html.matchAll(/\sid="([^"]+)"/g)].map((m) => decodeEntities(m[1] ?? "")));
}

const PAGE_SET = new Set(/** @type {readonly string[]} */ (CONTENT_PAGE_PATHS));
const PAGE_TWINS = new Set(CONTENT_PAGE_PATHS.map((p) => contentPageMarkdownPath(p)));

/** The namespaces this module can list completely. */
const OWNED = /^\/(?:research|teaching|software|recipes|writing)(?:\/|$)/;
/** Listed elsewhere: papers and citation exports, feeds, tag and series pages. */
const NOT_LISTED = /^\/(?:research\/publications|writing\/(?:tags|series|rss\.xml|feed\.json|atom\.xml))(?:[/.]|$)/;

/**
 * @param {string} path
 * @param {AddressBook} book
 * @param {number} [hops]
 * @returns {{ kind: "ok" | "unlisted" | "gone" | "draft" | "missing", path: string }}
 */
function resolve(path, book, hops = 0) {
  if (hops > 5) return { kind: "missing", path };
  const redirect = wordpressDisposition(path) ?? (() => {
    const moved = movedPathTarget(path);
    return moved === null ? null : { status: 301, location: moved };
  })();
  if (redirect && "status" in redirect && redirect.status === 410) return { kind: "gone", path };
  if (redirect && "location" in redirect && redirect.location) {
    return resolve(String(redirect.location).split("#")[0] ?? "", book, hops + 1);
  }
  if (!OWNED.test(path) || NOT_LISTED.test(path)) return { kind: "unlisted", path };
  if (PAGE_SET.has(path) || PAGE_TWINS.has(path)) return { kind: "ok", path };
  const procedure = path.replace(/(?:\.md|\/sheet)$/, "");
  if (book.procedurePaths.has(procedure)) return { kind: "ok", path };
  const visible = book.posts.get(path.replace(/\.md$/, ""));
  if (visible !== undefined) return { kind: visible ? "ok" : "draft", path };
  return { kind: "missing", path };
}

/**
 * @param {{ html: string }} page
 * @param {AddressBook} book
 * @returns {string[]}
 */
export function pageLinkErrors({ html }, book) {
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  for (const raw of [...html.matchAll(/\shref="([^"]*)"/g)].map((m) => decodeEntities(m[1] ?? ""))) {
    const href = SITE_HOST.test(raw) ? raw.replace(SITE_HOST, "") || "/" : raw;
    if (!href.startsWith("/") || href.startsWith("//") || seen.has(href)) continue;
    seen.add(href);
    const [pathAndQuery = "", anchor] = href.split("#");
    const path = (pathAndQuery.split("?")[0] ?? "").replace(/(.)\/+$/, "$1");
    const found = resolve(path, book);
    if (found.kind === "gone") errors.push(`the link ${href} goes to ${path}, which the site answers 410 Gone`);
    else if (found.kind === "draft") errors.push(`the link ${href} goes to a draft or scheduled post, which every reader gets a 404 for`);
    else if (found.kind === "missing") errors.push(`the link ${href} goes to ${found.path}, which this site does not serve`);
    else if (found.kind === "ok" && anchor && found.path === path) {
      const ids = book.idsOf(found.path);
      if (ids && !ids.has(safeDecode(anchor))) errors.push(`the link ${href} names an anchor that ${found.path} does not have`);
    }
  }
  return errors;
}

app/lib/podcast/feed.mjs.source:
// Pure, so node:test and the CSP builder can import it. Every feed URL is checked against a host
// allowlist; the audio list is what workers/csp.mjs writes into `media-src`, so the two cannot disagree.

import { decodeEntities } from "../publications/entities.mjs";

export const PODCAST_FEED_URL = "https://germomics.com/feed/podcast/";

export const PODCAST_SITE_URL = "https://germomics.com/";

// `op3.dev` is the feed's analytics prefix and 302s to `media.germomics.com`; CSP checks the redirect
// target too, so both are listed.
export const PODCAST_AUDIO_HOSTS = ["op3.dev", "media.germomics.com"];

const EPISODE_PAGE_HOSTS = ["germomics.com", "www.germomics.com"];

/**
 * @typedef {{
 *   guid: string,
 *   title: string,
 *   link: string,
 *   publishedAt: string,
 *   durationSeconds: number | null,
 *   description: string,
 *   audioUrl: string,
 *   audioType: string,
 *   season: number | null,
 *   episode: number | null,
 * }} PodcastEpisode
 */

/**
 * The shared decoder, plus `&nbsp;`: podcast hosts write it in show notes, and every whitespace run
 * here collapses to one space anyway. Replaced before decoding, so `&amp;nbsp;` still reads literally.
 *
 * @param {string} text
 */
function decodeFeedEntities(text) {
  return decodeEntities(text.replace(/&nbsp;/g, " "));
}

/**
 * @param {string} xml @param {string} tag
 */
function textOf(xml, tag) {
  const escaped = tag.replace(":", "\\:");
  const match = xml.match(new RegExp(`<${escaped}(?:\\s[^>]*)?>([\\s\\S]*?)</${escaped}>`));
  if (!match) return "";
  const raw = (match[1] ?? "").replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1");
  return decodeFeedEntities(raw.replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
}

/** @param {string} xml @param {string} tag @param {string} attr */
function attrOf(xml, tag, attr) {
  const element = xml.match(new RegExp(`<${tag.replace(":", "\\:")}\\s[^>]*>`));
  if (!element) return "";
  const value = element[0].match(new RegExp(`\\s${attr}="([^"]*)"`));
  return value ? decodeFeedEntities(value[1] ?? "") : "";
}

/**
 * @param {string} value @param {readonly string[]} hosts
 */
function allowedHttpsUrl(value, hosts) {
  try {
    const url = new URL(value);
    if (url.protocol !== "https:" || url.username || url.password || url.port) return null;
    return hosts.includes(url.hostname) ? url.href : null;
  } catch {
    return null;
  }
}

/**
 * @param {string} value
 */
export function parseDuration(value) {
  if (!/^\d+(:\d{1,2}){0,2}$/.test(value)) return null;
  return value.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}

/** @param {string} value */
function positiveInt(value) {
  return /^\d+$/.test(value) && Number(value) > 0 ? Number(value) : null;
}

/**
 * @param {string} xml
 * @returns {PodcastEpisode[]}
 */
export function parsePodcastFeed(xml) {
  /** @type {PodcastEpisode[]} */
  const episodes = [];
  for (const [, item = ""] of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
    const title = textOf(item, "title");
    const guid = textOf(item, "guid");
    const link = allowedHttpsUrl(textOf(item, "link"), EPISODE_PAGE_HOSTS);
    const audioUrl = allowedHttpsUrl(attrOf(item, "enclosure", "url"), PODCAST_AUDIO_HOSTS);
    const audioType = attrOf(item, "enclosure", "type");
    const published = new Date(textOf(item, "pubDate"));
    if (!title || !guid || !link || !audioUrl || !audioType.startsWith("audio/")) continue;
    if (Number.isNaN(published.getTime())) continue;
    episodes.push({
      guid,
      title,
      link,
      publishedAt: published.toISOString(),
      durationSeconds: parseDuration(textOf(item, "itunes:duration")),
      description: textOf(item, "description"),
      audioUrl,
      audioType,
      season: positiveInt(textOf(item, "itunes:season")),
      episode: positiveInt(textOf(item, "itunes:episode")),
    });
  }
  return episodes.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
}

app/lib/publications/export-response.mjs.source:
import { LICENSE_LINK } from "../license.mjs";
import { ASSET_PREFIX } from "../media/classify.mjs";
import { PUBLICATIONS_CACHE_TAG } from "./paths.mjs";

/**
 * A second copy of the index page's set (app/lib/publications/listing.mjs) on purpose.
 * check:machine-readable asserts the two agree.
 *
 * @type {Set<string>}
 */
export const SHOWCASE_TYPES = new Set([
  "article",
  "review",
  "chapter",
  "teaching-resource",
]);

/**
 * noindex: these are alternative representations of indexable pages. charset stated because names
 * carry diacritics. The dustin-edwards- prefix and the cache tag a save purges are added here so no route can
 * forget them.
 *
 * @param {string} type the media type, without parameters
 * @param {string} cacheControl
 * @param {string} filename the file's name after the prefix, e.g. `publications.bib`
 */
export function exportHeaders(type, cacheControl, filename) {
  if (!/^[a-z0-9][a-z0-9.-]*$/.test(filename)) {
    throw new Error(`exportHeaders: "${filename}" is not a safe download name`);
  }
  return {
    "content-type": `${type}; charset=utf-8`,
    "cache-control": cacheControl,
    "cache-tag": PUBLICATIONS_CACHE_TAG,
    "content-disposition": `inline; filename="${ASSET_PREFIX}${filename}"`,
    "x-robots-tag": "noindex",
    link: LICENSE_LINK,
  };
}

