/**
 * The site's terms are the license on every data set it publishes (Dustin, 2026-10-04): no open license for
 * now, so what may be done with the data is stated in one place. The address is stored once, here; the
 * Dataset JSON-LD names it as `license` (app/lib/seo.ts LICENSE_URL), and every download carries it as a
 * `Link: rel="license"` header, relative so a plain-node caller needs no origin.
 */
export const TERMS_PATH = "/terms";

/** The `Link` header value a data download carries: the CSV, JSON, RIS and BibTeX exports have no room for a field. */
export const LICENSE_LINK = `<${TERMS_PATH}>; rel="license"`;

app/lib/media/template-refs.mjs.source:
// Runs at BUILD time and ships as a committed artifact: the Worker has no repository, and its ASSETS
// binding can only fetch. The match is LITERAL, so a constructed path like `/diagrams/${id}.svg` is
// invisible; that is why the library says "no reference found" rather than "unused".

// `content/posts` is absent: post citations belong to the other tracker, and an asset must not claim both.
export const SOURCE_ROOTS = ["app", "workers"];

export const SOURCE_FILES = ["public/site.webmanifest", "content/features.json"];

// Each paper's file names its PDF by path (`pdfPath`) and each dictionary entry its pronunciation clip (`audio`), so
// these markdown files are sources: without them every hosted PDF and clip would read as unreferenced. Passed
// through unstripped, like JSON: the extracted text has apostrophes. Each cohort's file under content/roster names its
// photograph by path, so without it the nine photographs would read as unreferenced.
export const SOURCE_DIRECTORIES = ["content/publications", "content/dictionary", "content/roster"];

const SOURCE_EXTENSIONS = [".ts", ".tsx", ".mjs", ".js", ".css", ".json", ".webmanifest"];

// Checked first because `SOURCE_FILES` bypass the root rule. `assets.json` lists every asset path.
const SELF_REFERENTIAL = ["content/generated/assets.json"];

/**
 * @param {string} file repo-relative, forward slashes
 * @returns {boolean}
 */
export function isSourceFile(file) {
  if (SELF_REFERENTIAL.includes(file)) return false;
  if (SOURCE_FILES.includes(file)) return true;
  if (SOURCE_DIRECTORIES.some((dir) => file.startsWith(`${dir}/`) && file.endsWith(".md"))) return true;
  const root = file.split("/")[0] ?? "";
  if (!SOURCE_ROOTS.includes(root)) return false;
  return SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext));
}

/**
 * Prose about an asset is not a reference. A tokenizer, not a regex: stripping from `//` to end of line
 * would destroy every `https://` inside a string literal, which is where real references live.
 *
 * @param {string} text
 * @param {boolean} [cssOnly] true for `.css`, which has no line comments
 * @returns {string} the same length, with comment bytes blanked to spaces
 */
export function stripComments(text, cssOnly = false) {
  let out = "";
  let i = 0;
  /** @type {"code"|"line"|"block"|"'"|"\""|"`"} */
  let mode = "code";
  while (i < text.length) {
    const c = text[i];
    const next = text[i + 1];
    if (mode === "code") {
      if (c === "/" && next === "*") { mode = "block"; out += "  "; i += 2; continue; }
      if (!cssOnly && c === "/" && next === "/") { mode = "line"; out += "  "; i += 2; continue; }
      if (!cssOnly && (c === "'" || c === '"' || c === "`")) { mode = c; out += c; i += 1; continue; }
      if (cssOnly && (c === "'" || c === '"')) { mode = c; out += c; i += 1; continue; }
      out += c; i += 1; continue;
    }
    if (mode === "line") {
      if (c === "\n") { mode = "code"; out += c; i += 1; continue; }
      // Blanked rather than deleted, so offsets stay comparable and lines cannot join.
      out += " "; i += 1; continue;
    }
    if (mode === "block") {
      if (c === "*" && next === "/") { mode = "code"; out += "  "; i += 2; continue; }
      out += c === "\n" ? c : " "; i += 1; continue;
    }
    if (c === "\\") { out += text.slice(i, i + 2); i += 2; continue; }
    if (c === mode) { mode = "code"; out += c; i += 1; continue; }
    out += c; i += 1;
  }
  return out;
}

/**
 * Both ends must be boundaries: `/dustin-edwards-logo.svg` is a prefix of `/dustin-edwards-logo-dark.svg`,
 * and `"public/site.webmanifest"` ends with `/site.webmanifest`.
 *
 * @param {string} text the file contents
 * @param {string[]} assetPaths every known asset path
 * @returns {string[]} the subset referenced, in the order given
 */
export function referencesIn(text, assetPaths) {
  return assetPaths.filter((asset) => {
    let from = 0;
    for (;;) {
      const at = text.indexOf(asset, from);
      if (at < 0) return false;
      const before = at === 0 ? undefined : text[at - 1];
      const after = text[at + asset.length];
      /** @param {string | undefined} ch */
      const bounded = (ch) => ch === undefined || !/[A-Za-z0-9._~/-]/.test(ch);
      if (bounded(before) && bounded(after)) return true;
      from = at + 1;
    }
  });
}

/**
 * Sorted, so the generated artifact does not churn with directory order and a gate can byte-compare it.
 *
 * @param {Array<{ file: string, assets: string[] }>} scanned
 * @returns {{ generated: number, refs: Record<string, string[]> }}
 */
export function foldRefs(scanned) {
  /** @type {Record<string, string[]>} */
  const refs = {};
  for (const { file, assets } of scanned) {
    for (const asset of assets) {
      if (!refs[asset]) refs[asset] = [];
      if (!refs[asset].includes(file)) refs[asset].push(file);
    }
  }
  /** @type {Record<string, string[]>} */
  const sorted = {};
  for (const asset of Object.keys(refs).sort()) sorted[asset] = (refs[asset] ?? []).slice().sort();
  return { generated: Object.keys(sorted).length, refs: sorted };
}

app/lib/negotiate.mjs.source:
// Plain .mjs so `node --test` can import it; the types are JSDoc under checkJs.

/**
 * @param {Request} request
 * @returns {Map<string, number>}
 */
export function acceptQValues(request) {
  /** @type {Map<string, number>} */
  const values = new Map();
  const accept = request.headers.get("accept");
  if (!accept) return values;

  for (const part of accept.split(",")) {
    const [range, ...params] = part.trim().split(";");
    const type = (range ?? "").trim().toLowerCase();
    if (!type) continue;

    let q = 1;
    for (const param of params) {
      const [key, value] = param.trim().split("=");
      if (key?.trim().toLowerCase() === "q") {
        const parsed = Number.parseFloat(value ?? "");
        if (!Number.isNaN(parsed)) q = parsed;
      }
    }

    values.set(type, Math.max(values.get(type) ?? -1, q));
  }

  return values;
}

/** Wildcards count as votes for HTML, the default representation. */
const HTML_RANGES = ["text/html", "text/*", "*/*"];

/**
 * @param {Map<string, number>} values
 * @returns {number}
 */
function htmlWeight(values) {
  let html = -1;
  for (const range of HTML_RANGES) {
    html = Math.max(html, values.get(range) ?? -1);
  }
  return html;
}

/**
 * A tie goes to HTML, the safer default for a client that guessed.
 *
 * @param {Request} request @param {string} wanted
 * @returns {boolean}
 */
export function prefersType(request, wanted) {
  const values = acceptQValues(request);
  const target = values.get(wanted.toLowerCase()) ?? -1;
  return target > 0 && target > htmlWeight(values);
}

/**
 * `caches.default` ignores `Vary: Accept`, so a non-HTML request must bypass the
 * Worker's cache or it is served the stored HTML. Deliberately wider than the
 * routes that negotiate: being wide costs a miss, being narrow serves wrong bytes.
 *
 * @param {Request} request
 * @returns {boolean}
 */
export function negotiatesAwayFromHtml(request) {
  const values = acceptQValues(request);
  if (values.size === 0) return false;

  const html = htmlWeight(values);
  for (const [type, q] of values) {
    if (HTML_RANGES.includes(type)) continue;
    if (q > 0 && q > html) return true;
  }
  return false;
}

app/lib/path-moves.mjs.source:
/**
 * The 2026-09-27 site structure moved two sections: /blog to /writing, and /publications to
 * /research/publications. Nothing linked to the new site's old addresses yet, but they were public,
 * so each keeps answering with a 301 to the same page at its new address. /playground was removed
 * on 2026-09-28, so it and everything under it answers one 301 to /. Abscissa was renamed Enarratio
 * on 2026-09-29, so /software/abscissa and its markdown twin answer a 301 to /software/enarratio.
 * The family of systems became one page on 2026-10-18: each /systems/<id> answers a 301 to
 * /systems?system=<id>, the same page with that system chosen, and each /systems/<id>.md to /systems.md,
 * which holds every system.
 * Runs in the gateway, before the renamed-post and PDF maps, so an old post slug or an old PDF name
 * still resolves in one hop.
 *
 * The old feed addresses are not moved: they are routes of their own (app/routes.ts) and keep
 * answering with the feed, because a feed reader may never follow a redirect.
 */

const MOVES = /** @type {const} */ ([
  ["/blog", "/writing"],
  ["/publications", "/research/publications"],
  ["/software/abscissa", "/software/enarratio"],
]);

/** Whole paths, not prefixes. `/projects/foo` is not a page and must not move. */
const EXACT_MOVES = new Map([
  ["/projects", "/software"],
  ["/projects/", "/software"],
  ["/phage-discovery", "/teaching/phage-discovery#roster"],
  ["/phage-discovery/", "/teaching/phage-discovery#roster"],
]);

/** A system's old page or twin (app/lib/systems.mjs ids): the id, and the `.md` if it is the twin. */
const OLD_SYSTEM_PAGE = /^\/systems\/([a-z0-9][a-z0-9-]{0,63})(\.md)?$/;

/**
 * Sections removed outright, with no page of their own to move to: the section and everything under
 * or beside it answers one 301 to the home page.
 */
const RETIRED_TO_HOME = /** @type {const} */ (["/playground"]);

/** The feed files a reader subscribes to, under /blog, /blog/tags/<tag> or /blog/series/<series>. */
const FEED_FILES = new Set(["rss.xml", "feed.json", "atom.xml"]);

/**
 * @param {string} rest the path after `/blog`, starting with `/`
 * @returns {boolean}
 */
function isLegacyFeed(rest) {
  const parts = rest.split("/").filter(Boolean);
  const file = parts.at(-1) ?? "";
  if (!FEED_FILES.has(file)) return false;
  if (parts.length === 1) return true;
  // /blog/tags/<tag>/rss.xml and /blog/series/<series>/feed.json; atom exists only for the whole site.
  return parts.length === 3 && (parts[0] === "tags" || parts[0] === "series") && file !== "atom.xml";
}

/**
 * Returns a path, not a URL, so the redirect cannot be talked into naming another host. The path may
 * carry a query of its own (a chosen system); the gateway keeps the request's other parameters with it.
 *
 * @param {string} pathname the request's pathname, already decoded by URL
 * @returns {string | null} the new path, or null when this path did not move
 */
export function movedPathTarget(pathname) {
  if (typeof pathname !== "string") return null;
  if (EXACT_MOVES.has(pathname)) return EXACT_MOVES.get(pathname) ?? null;
  const system = OLD_SYSTEM_PAGE.exec(pathname);
  if (system) return system[2] ? "/systems.md" : `/systems?system=${system[1]}`;
  for (const from of RETIRED_TO_HOME) {
    const next = pathname.charAt(from.length);
    if (pathname === from || (pathname.startsWith(from) && (next === "/" || next === "."))) return "/";
  }
  for (const [from, to] of MOVES) {
    if (pathname === from) return to;
    // `/publications.bib` and friends sit beside the section rather than under it.
    const next = pathname.charAt(from.length);
    if (!pathname.startsWith(from) || (next !== "/" && next !== ".")) continue;
    const rest = pathname.slice(from.length);
    if (from === "/blog" && isLegacyFeed(rest)) return null;
    return `${to}${rest}`;
  }
  return null;
}

app/lib/post-order.mjs.source:
// The order posts are listed in, newest first, as one rule for the two places that apply it: the D1 listing
// queries (app/db/posts.ts, newestFirstOrder) and the header's build-time list (scripts/lib/nav-data.mjs).
//
// 1. Publish instant, latest first.
// 2. Posts that share an instant: a series stays together and reads latest part first (the newest part of a
//    series is its newest post). A series sits among unrelated posts where its latest row would.
// 3. Otherwise the later row first. The database breaks that tie by row id; the build cannot see ids, so it
//    passes the slug, because rows are inserted in slug order (scripts/build-content.mjs).
//
// Concretely: sort by instant, then by the group key (the largest tie-break value among the posts sharing the
// instant and series, or the post's own value when it has no series), then by part, then by the tie-break
// value. That is a total order, which "part descending within a series, the tie-break otherwise" alone is not.

/**
 * @template {{ publishAt: string, series: string | null, part: number | null }} P
 * @param {P[]} posts
 * @param {(post: P) => string | number} tie the row id in a database, the slug in the build
 * @returns {P[]} a new array, newest first
 */
export function newestFirst(posts, tie) {
  /** @type {Map<string, string | number>} */
  const latest = new Map();
  const groupOf = (/** @type {P} */ p) => `${p.publishAt}\u0000${p.series}`;
  for (const p of posts) {
    if (p.series === null) continue;
    const seen = latest.get(groupOf(p));
    if (seen === undefined || tie(p) > seen) latest.set(groupOf(p), tie(p));
  }
  const key = (/** @type {P} */ p) => (p.series === null ? tie(p) : /** @type {string | number} */ (latest.get(groupOf(p))));
  const desc = (/** @type {string | number} */ a, /** @type {string | number} */ b) => (a === b ? 0 : a < b ? 1 : -1);
  return [...posts].sort(
    (a, b) => desc(a.publishAt, b.publishAt) || desc(key(a), key(b)) || desc(a.part ?? 0, b.part ?? 0) || desc(tie(a), tie(b)),
  );
}

app/lib/publications/listing.mjs.source:
/**
 * The publication index (docs/PUBLICATIONS.md): its fields declared once for Capsomer's catalog, so the search box, the
 * topic and other facets, the sort menu, the year headings and the counts all come from this one declaration. Pure
 * over the query string and the papers it is handed. The route adds the citation counts (a D1 read) and the page copy.
 *
 * What did not change, because search engines and the machine-readable gates hold it: `?topic=` is the address of a
 * topic's papers, and exactly the four bare single-topic addresses canonicalise to themselves (`soleTopic`); every other
 * address is a view of the base page.
 */

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behaviour/catalog";

import { decodeEntities } from "./entities.mjs";
import { TOPICS, TOPIC_IDS } from "./topics.mjs";

/** @typedef {import("./types.ts").Publication} Publication */
/** @typedef {import("./types.ts").PublicationType} PublicationType */
/** @typedef {import("./types.ts").TopicId} TopicId */

/**
 * Conference abstracts stay in the data file, which the CV also reads, and are excluded here.
 *
 * @type {Set<PublicationType>}
 */
export const SHOWCASE_TYPES = new Set([
  "article",
  "review",
  "chapter",
  "teaching-resource",
]);

export const PUBLICATIONS_BASE = "/research/publications";

const TYPE_LABELS = /** @type {Record<string, string>} */ ({
  article: "Article",
  review: "Review",
  chapter: "Chapter",
  "teaching-resource": "Teaching resource",
});

/** The journal, volume and pages as the page prints them, entities decoded (the year has its own column). @param {Publication} p */
export function venue(p) {
  return decodeEntities([p.journal, p.volume, p.pages].filter(Boolean).join(", "));
}

/** The papers' catalog. Newest first by default, under a heading for each year; any search or other sort is flat. */
export const PUBLICATIONS = defineCatalog(
  /** @type {import("capsomer/behaviour/catalog").CatalogDefinition<Publication>} */ ({
    id: "papers",
    noun: ["paper", "papers"],
    basePath: PUBLICATIONS_BASE,
    itemKey: (p) => p.id,
    defaultSort: "-year",
    group: { field: "year" },
    fields: [
      { key: "title", label: "Title", value: (p) => decodeEntities(p.title), search: 3, sort: true, column: { header: "Paper" } },
      { key: "authors", label: "Authors", value: (p) => p.authors.map(decodeEntities), search: 1 },
      { key: "journal", label: "Journal", value: (p) => venue(p), search: 2, column: { header: "Journal", drop: 1 } },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { labels: { asc: "oldest first", desc: "newest first" } },
        column: { header: "Year", align: "end", hideWhenGrouped: true },
      },
      {
        key: "topic",
        label: "Topic",
        value: (p) => p.topics,
        facet: { kind: "many", general: true, order: TOPICS.map((t) => t.id), label: (v) => TOPICS.find((t) => t.id === v)?.label ?? v },
      },
      { key: "type", label: "Type", value: (p) => p.type, facet: { kind: "many", label: (v) => TYPE_LABELS[v] ?? v } },
      // Chosen with `?selected=1`, as the page's "Selected" filter always was.
      { key: "selected", label: "Selected", value: (p) => (p.selected ? "1" : null), facet: { kind: "one", label: () => "Selected papers" } },
      { key: "access", label: "Access", value: (p) => (p.isOpenAccess ? "open" : null), facet: { kind: "one", label: () => "Open access" } },
    ],
  }),
);

/**
 * The address a request written in the old parameters should have, or null. The page used `?sort=year-desc|year-asc|title`
 * and `?selected=1|true`; the catalog says `sort=-year|year|title` and `selected=1`. A link in the wild keeps working: it
 * is sent, once, to the same view at its new address. A request with none of the old spellings is left alone.
 *
 * @param {URL} url
 */
export function legacyAddress(url) {
  const params = url.searchParams;
  const sort = params.get("sort");
  const oldSort = sort === "year-desc" || sort === "year-asc";
  const oldSelected = (params.get("selected") ?? "").toLowerCase() === "true";
  if (!oldSort && !oldSelected) return null;
  const next = new URLSearchParams(params);
  if (sort === "year-desc") next.delete("sort");
  if (sort === "year-asc") next.set("sort", "year");
  if (oldSelected) next.set("selected", "1");
  return queryCatalog(PUBLICATIONS, [], parseCatalogParams(PUBLICATIONS, next)).href();
}

/**
 * Only the four bare single-topic URLs self-canonical: the rest are subsets or orderings, and q is unbounded.
 *
 * @param {URLSearchParams} params
 * @returns {TopicId | null}
 */
export function soleTopic(params) {
  const topics = params.getAll("topic").filter((t) => TOPIC_IDS.has(t));
  const KNOWN_PARAMS = new Set(["topic", "q", "sort", "selected"]);
  const hasUnknownParam = [...params.keys()].some((k) => !KNOWN_PARAMS.has(k));
  return topics.length === 1 &&
    params.getAll("topic").length === 1 &&
    !params.has("q") &&
    !params.has("sort") &&
    !params.has("selected") &&
    !hasUnknownParam
    ? /** @type {TopicId} */ (topics[0])
    : null;
}

/**
 * The page's state for an address: the showcase papers run through the catalog, with the span the header states and the
 * canonical topic. Everything shown is in `result`.
 *
 * @param {URLSearchParams} params
 * @param {Publication[]} publications every published paper, newest first (app/db/publications.ts)
 */
export function publicationListing(params, publications) {
  const showcase = publications.filter((p) => SHOWCASE_TYPES.has(p.type));
  const result = queryCatalog(PUBLICATIONS, showcase, parseCatalogParams(PUBLICATIONS, params));
  const items = result.rows;
  const span = {
    papers: items.length,
    firstYear: items.length > 0 ? Math.min(...items.map((p) => p.year)) : null,
    lastYear: items.length > 0 ? Math.max(...items.map((p) => p.year)) : null,
    venues: new Set(items.map((p) => p.journal).filter(Boolean)).size,
  };
  return { items, result, span, soleTopic: soleTopic(params), total: showcase.length };
}

app/lib/read-capped.mjs.source:
import { errorMessage } from "./error-message.mjs";

/**
 * Counts chunks as they arrive. The client's declared length must never permit: it can be absent
 * or understated, and `request.text()` materializes the whole body before any slice runs. A stream
 * that errors mid-read THROWS: no bytes are a safe stand-in, because every caller parses what it gets.
 *
 * @param {{ body: ReadableStream<Uint8Array> | null }} source Anything with a body stream.
 * @param {number} max Hard ceiling in bytes.
 * @returns {Promise<Uint8Array | null>} The body, or null when over the cap.
 */
export async function readCappedBytes(source, max) {
  if (!source.body) return new Uint8Array(0);
  const reader = source.body.getReader();
  /** @type {Uint8Array[]} */
  const chunks = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!value) continue;
      total += value.byteLength;
      if (total > max) {
        // NULL rather than a truncated body, so the caller answers 413 instead of logging a
        // fragment of a body we should not have taken.
        await reader.cancel();
        return null;
      }
      chunks.push(value);
    }
  } catch (error) {
    throw new Error(
      `the body stream failed after ${total} bytes: ` +
        `${errorMessage(error)}`,
      { cause: error },
    );
  }
  const joined = new Uint8Array(total);
  let at = 0;
  for (const chunk of chunks) {
    joined.set(chunk, at);
    at += chunk.byteLength;
  }
  return joined;
}

/**
 * `readCappedBytes`, decoded as UTF-8: "" for no body, null when over the cap.
 *
 * @param {{ body: ReadableStream<Uint8Array> | null }} source Anything with a body stream.
 * @param {number} max Hard ceiling in bytes.
 * @returns {Promise<string | null>}
 */
export async function readCapped(source, max) {
  const bytes = await readCappedBytes(source, max);
  return bytes === null ? null : new TextDecoder().decode(bytes);
}

