// The admin's Knowledge Base page (docs/KNOWLEDGE-BASE.md, step 2), the part that needs no runtime: its tabs and their
// counts, the search over a base's entries, and the Needs info list, every recorded gap of every entry and registry item
// on one screen. Pure, so node:test holds it; the route passes in the rows it read from D1. Read-only: nothing here writes.

import { foldText } from "../lib/cv/view.mjs";
import { BASES } from "./bases.mjs";
import { labelGaps } from "./gap-labels.mjs";
import { hasItemPage, itemPath, kindPath } from "./registry/catalog.mjs";
import { isGap } from "./registry/compile.mjs";
import { KINDS } from "./registry/kinds.mjs";

export const KB_ADMIN_PATH = "/admin/kb";

/** Where an entry's file is edited (step 3). @param {string} slug */
export const entryEditHref = (slug) => `${KB_ADMIN_PATH}/entry/${slug}`;

/** Where a registry item's file is edited (step 3). @param {string} kind @param {string} id */
export const itemEditHref = (kind, id) => `${KB_ADMIN_PATH}/item/${kind}/${id}`;

/** The tab that lists every gap, beside one tab per base. */
export const NEEDS_INFO = "needs-info";

/**
 * @typedef {{
 *   slug: string,
 *   path: string,
 *   profile: string,
 *   title: string,
 *   description: string,
 *   draft: boolean,
 *   version: string | null,
 *   updated: string | null,
 *   gaps: Array<{ field: string, reason: string, where?: string[], section?: string }>,
 * }} KbEntry
 *
 * @typedef {{ kind: string, id: string, name: string, status: string, fields: Record<string, unknown> }} KbItem
 *
 * @typedef {{ what: string, kindLabel: string, href: string, editHref: string, field: string, label: string, reason: string }} KbGap
 */

/** The tab a `?tab=` value names, else the first base. @param {string | null} value */
export function resolveTab(value) {
  if (value === NEEDS_INFO || BASES.some((base) => base.id === value)) return /** @type {string} */ (value);
  return /** @type {string} */ (BASES[0]?.id);
}

/** A tab's address, keeping the search only where it still applies (a base's list). @param {string} tab @param {string} [q] */
export function tabHref(tab, q = "") {
  const params = new URLSearchParams({ tab });
  if (q && tab !== NEEDS_INFO) params.set("q", q);
  return `${KB_ADMIN_PATH}?${params}`;
}

/**
 * Every tab with its count, read from the same rows the lists are drawn from: one per base, then Needs info.
 *
 * @param {KbEntry[]} entries
 * @param {KbGap[]} gaps
 */
export function kbTabs(entries, gaps) {
  return [
    ...BASES.map((base) => ({ id: base.id, label: base.name, count: entries.filter((e) => e.profile === base.profile).length })),
    { id: NEEDS_INFO, label: "Needs info", count: gaps.length },
  ];
}

/**
 * A base's entries, narrowed by a search over the title, description and slug (case and accents folded), in title order.
 *
 * @param {KbEntry[]} entries
 * @param {string} tab
 * @param {string} [q]
 */
export function baseEntries(entries, tab, q = "") {
  const base = BASES.find((b) => b.id === tab);
  if (!base) return [];
  const needle = foldText(q);
  return entries
    .filter((e) => e.profile === base.profile)
    .filter((e) => needle === "" || foldText(`${e.title} ${e.description} ${e.slug}`).includes(needle))
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }));
}

/** Where an item is read: its own page, or its kind's table where the kind has no item pages. @param {KbItem} item */
function itemHref(item) {
  return hasItemPage(item.kind) ? itemPath(item.kind, item.id) : kindPath(item.kind);
}

/**
 * Every recorded gap (`MISSING: <why>`), entries first in title order, then registry items in the registry's order, each
 * with the field and the reason as written.
 *
 * @param {KbEntry[]} entries
 * @param {KbItem[]} items
 * @returns {KbGap[]}
 */
export function needsInfo(entries, items) {
  const profileName = Object.fromEntries(BASES.map((base) => [base.profile, base.singular]));
  const fromEntries = [...entries]
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }))
    .flatMap((e) =>
      labelGaps(e.gaps, e.profile).map((gap) => ({
        what: e.title,
        kindLabel: profileName[e.profile] ?? e.profile,
        href: e.path,
        editHref: `${entryEditHref(e.slug)}#${gap.anchor}`,
        field: gap.field,
        label: gap.label,
        reason: gap.reason,
      })),
    );
  const fromItems = items.flatMap((item) =>
    labelGaps(
      Object.entries(item.fields)
        .filter(([, value]) => isGap(value))
        .map(([field, value]) => ({ field, reason: String(value).replace(/^MISSING:\s*/, "") })),
      null,
    ).map((gap) => ({
      what: item.name,
      kindLabel: capitalise(KINDS[item.kind]?.singular ?? item.kind),
      href: itemHref(item),
      editHref: `${itemEditHref(item.kind, item.id)}#${gap.anchor}`,
      field: gap.field,
      label: gap.label,
      reason: gap.reason,
    })),
  );
  return [...fromEntries, ...fromItems];
}

/** @param {string} word */
function capitalise(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

app/kb/procedures/compile.mjs.source:
// One door from a procedure file to everything derived from it: parse, validate, render, the markdown
// twin and the search input. check:protocols, sync:content and the operator API's save_procedure all
// call compileProcedure, so a file CI passes is the file the save tool accepts and the page draws.

import { gitBlobSha } from "../../lib/content/hashes.mjs";
import { itemPath } from "../registry/catalog.mjs";
import { NON_STRAIN_ORGANISMS } from "./taxonomy.mjs";
import { parseProcedure, procedurePath } from "./parse.mjs";
import { procedureSearchInput, renderProcedure } from "./render.mjs";
import { validateProcedure } from "./validate.mjs";

/** The file name a slug is written in; the same rule as a post's. */
export const PROCEDURE_SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/**
 * @param {{
 *   slug: string,
 *   raw: string,
 *   pipeline: { renderBody: import("./render.mjs").RenderBody, findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> },
 *   resolveImage?: (src: string) => Promise<{ width: number, height: number }>,
 *   registry?: {
 *     primers: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredPrimer>>,
 *     strains: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredStrain>>,
 *     reagents: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredReagent>>,
 *     equipment: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredEquipment>>,
 *   },
 * }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[], gaps: Array<{ field: string, reason: string }> }
 *   | { ok: true, errors: [], gaps: Array<{ field: string, reason: string }>, record: import("./render.mjs").ProcedureRecord,
 *       markdown: string, searchInput: ReturnType<typeof procedureSearchInput>, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compileProcedure({ slug, raw, pipeline, resolveImage, registry }) {
  if (!PROCEDURE_SLUG.test(slug)) {
    return { ok: false, errors: [`"${slug}" is not a lowercase kebab-case slug`], gaps: [] };
  }
  const file = procedurePath(slug);
  const dashes = pipeline.findWideDashes(raw).map(
    (hit) => `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`,
  );
  const parsed = parseProcedure({ file, raw });
  // A protocol names its primers by their id in the lab registry and stores no sequence (docs/REGISTRY.md); the registry's
  // rows are read here, so the record carries them and a frozen version freezes them. A caller with no registry cannot
  // compile a protocol that names primers: writing a record with no primer table would be silent.
  const named = Array.isArray(parsed.data.primers) ? parsed.data.primers.flatMap((p) => (typeof p?.primer === "string" ? [p.primer] : [])) : [];
  const namedStrains = Array.isArray(parsed.data.host_strain) ? parsed.data.host_strain.flatMap((s) => (typeof s?.strain === "string" ? [s.strain] : [])) : [];
  // An organism that is not a non-strain organism is a strain of the registry, so it is read from there too.
  const organismIds = Array.isArray(parsed.data.organism) ? parsed.data.organism.filter((id) => typeof id === "string" && !Object.hasOwn(NON_STRAIN_ORGANISMS, id)) : [];
  // A material that is a reagent of the registry names it by id; its facts are the registry's, not typed in the protocol.
  const namedReagents = Array.isArray(parsed.data.materials) ? parsed.data.materials.flatMap((m) => (typeof m?.reagent === "string" ? [m.reagent] : [])) : [];
  // An equipment entry that is an item of the registry names it by id.
  const namedEquipment = Array.isArray(parsed.data.equipment) ? parsed.data.equipment.flatMap((e) => (typeof e?.equipment === "string" ? [e.equipment] : [])) : [];
  if ((named.length > 0 || namedStrains.length > 0 || organismIds.length > 0 || namedReagents.length > 0 || namedEquipment.length > 0) && !registry) {
    return { ok: false, errors: ["this compile was given no lab registry, so the primers, host strains, organisms, reagents and equipment the file names cannot be read"], gaps: [] };
  }
  const primerRows = named.length > 0 && registry ? await registry.primers(named) : new Map();
  const strainIds = [...new Set([...namedStrains, ...organismIds])];
  const strainRows = strainIds.length > 0 && registry ? await registry.strains(strainIds) : new Map();
  const equipmentIds = [...new Set(namedEquipment)];
  const equipmentRows = equipmentIds.length > 0 && registry ? await registry.equipment(equipmentIds) : new Map();
  const reagentIds = [...new Set(namedReagents)];
  const reagentRows = reagentIds.length > 0 && registry ? await registry.reagents(reagentIds) : new Map();
  const { errors, gaps } = validateProcedure(parsed, { slug, primers: new Set(primerRows.keys()), strains: new Set(strainRows.keys()), reagents: new Set(reagentRows.keys()), equipment: new Set(equipmentRows.keys()) });
  // A draft primer is the admin's alone, so a published protocol may not print it.
  if (parsed.data.draft !== true) {
    for (const [id, row] of primerRows) if (row.status === "draft") errors.push(`primers[${id}] is a draft in the lab registry, so a published protocol cannot print it`);
    for (const [id, row] of strainRows) if (row.status === "draft") errors.push(`strain ${id} is a draft in the lab registry, so a published protocol cannot name it`);
    for (const [id, row] of reagentRows) if (row.status === "draft") errors.push(`reagent ${id} is a draft in the lab registry, so a published protocol cannot name it`);
    for (const [id, row] of equipmentRows) if (row.status === "draft") errors.push(`equipment ${id} is a draft in the lab registry, so a published protocol cannot name it`);
  }
  errors.unshift(...dashes);
  if (errors.length > 0) return { ok: false, errors, gaps };

  let record;
  try {
    record = await renderProcedure({
      slug,
      parsed,
      gaps,
      renderBody: pipeline.renderBody,
      resolveImage,
      primerRows: named.flatMap((id) => (primerRows.has(id) ? [primerRows.get(id)] : [])),
      // The strain's page is where the protocol links it, computed from its id here and not typed anywhere.
      strainRows: namedStrains.flatMap((id) => (strainRows.has(id) ? [{ ...strainRows.get(id), path: itemPath("strain", id) }] : [])),
      // The reagents the materials name, as the registry states them, so the table shows where each comes from and types none.
      reagentRows: reagentIds.flatMap((id) => (reagentRows.has(id) ? [reagentRows.get(id)] : [])),
      // The equipment the list names, as the registry states it, so the table shows who makes each and types none.
      equipmentRows: equipmentIds.flatMap((id) => (equipmentRows.has(id) ? [equipmentRows.get(id)] : [])),
      // The words for each organism id the protocol names, from the registry (or the non-strain list), so the library needs no list of its own.
      organismNames: Object.fromEntries(
        (Array.isArray(parsed.data.organism) ? parsed.data.organism : []).flatMap((id) => {
          const words = Object.hasOwn(NON_STRAIN_ORGANISMS, id) ? /** @type {Record<string, string>} */ (NON_STRAIN_ORGANISMS)[id] : strainRows.get(id)?.organism;
          return words ? [[id, words]] : [];
        }),
      ),
    });
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : String(error)], gaps };
  }
  const searchInput = procedureSearchInput(record, parsed);
  return {
    ok: true,
    errors: [],
    gaps,
    record,
    markdown: searchInput.markdown,
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/kb/procedures/parse.mjs.source:
// Reads a procedure file (docs/PROCEDURES.md) into its structure: the front matter as written, then the
// body as an intro and sections, each section a run of prose blocks and step lists. Nothing here renders
// or judges; validate.mjs judges and render.mjs renders, so the check and the save tool read one parse.

import { slug as githubSlug } from "github-slugger";
import matter from "gray-matter";

import { readConditions, segmentText, tokenize } from "./marks.mjs";

export const PROCEDURES_DIR = "content/procedures";

/** The repository path of a procedure's file. */
export function procedurePath(/** @type {string} */ slug) {
  return `${PROCEDURES_DIR}/${slug}.md`;
}

/**
 * The heading id rehype-slug gives the same words, by the same library, so an anchor the old pages
 * published keeps working. A repeated heading's -1, -2 suffix is render.mjs's, which slugs the page in
 * one pass as rehype-slug does.
 *
 * @param {string} text
 */
export function headingId(text) {
  return githubSlug(text);
}

const FLAG_KEYS = /** @type {const} */ ({
  CRITICAL: "critical",
  "PAUSE POINT": "pause",
  WHY: "why",
  TROUBLESHOOTING: "troubleshooting",
  EXPECT: "expect",
  SPIN: "spin",
  CALC: "calc",
  CHALLENGE: "challenge",
  SOLUTION: "solution",
});

/** The platforms a fenced block may name (docs/PROCEDURES.md, S4): a how-to's commands where they differ by system. */
export const PLATFORMS = /** @type {const} */ ({ linux: "Linux", macos: "macOS", windows: "Windows" });

/**
 * @typedef {{ critical: string[], pause: string[], why: string[], troubleshooting: string[], expect: string[], spin: string[], calc: string[], challenge: string[], solution: string[] }} Flags
 * @typedef {{ lang: string, code: string, output: string | null, platform: string | null }} Command
 * @typedef {{
 *   number: number,
 *   line: number,
 *   source: string,
 *   segments: import("./marks.mjs").Segment[],
 *   flags: Flags,
 *   commands: Command[],
 *   photos: Array<{ alt: string, src: string }>,
 * }} Step
 * @typedef {{ type: "prose", markdown: string } | { type: "steps", steps: Step[] }} Block
 * @typedef {{ title: string, id: string, custom: boolean, line: number, blocks: Block[] }} Section
 */

/**
 * YAML dates arrive as Date objects; the record keeps the ISO day the file wrote.
 *
 * @param {unknown} value
 * @returns {unknown}
 */
function plain(value) {
  if (value instanceof Date) return value.toISOString().slice(0, 10);
  if (Array.isArray(value)) return value.map(plain);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, plain(v)]));
  }
  return value;
}

/**
 * The lines under a step, with its indentation removed, split into the step's own words, its flags,
 * its commands and its photos.
 *
 * @param {string} first the text after "N. "
 * @param {string[]} rest the indented lines under it, dedented
 * @param {number} line
 * @param {number} number
 * @returns {{ step: Step, problems: string[] }}
 */
function readStep(first, rest, line, number) {
  /** @type {string[]} */
  const problems = [];
  /** @type {string[]} */
  const words = [first];
  /** @type {Flags} */
  const flags = { critical: [], pause: [], why: [], troubleshooting: [], expect: [], spin: [], calc: [], challenge: [], solution: [] };
  /** @type {Command[]} */
  const commands = [];
  /** @type {Array<{ alt: string, src: string }>} */
  const photos = [];
  /** @type {keyof Flags | null} */
  let openFlag = null;

  for (let i = 0; i < rest.length; i += 1) {
    const text = rest[i] ?? "";
    // "```bash platform=linux": a language, then attributes; platform is the only one the format has.
    const fence = /^```(\S*)((?:\s+[a-z]+=\S+)*)\s*$/.exec(text);
    if (fence) {
      openFlag = null;
      const lang = fence[1] ?? "";
      const attrs = Object.fromEntries([...(fence[2] ?? "").matchAll(/([a-z]+)=(\S+)/g)].map((m) => [m[1], m[2]]));
      for (const key of Object.keys(attrs)) if (key !== "platform") problems.push(`line ${line}: step ${number} has a code block with "${key}=", and platform= is the only attribute a block takes`);
      /** @type {string[]} */
      const code = [];
      i += 1;
      while (i < rest.length && !/^```\s*$/.test(rest[i] ?? "")) {
        code.push(rest[i] ?? "");
        i += 1;
      }
      if (i >= rest.length) problems.push(`line ${line}: step ${number} has a code block that is never closed`);
      if (lang === "output") {
        const target = commands[commands.length - 1];
        if (!target) problems.push(`line ${line}: step ${number} has an output block with no command before it`);
        else target.output = code.join("\n");
      } else {
        commands.push({ lang, code: code.join("\n"), output: null, platform: attrs.platform ?? null });
      }
      continue;
    }
    const flag = /^>\s*(CRITICAL|PAUSE POINT|WHY|TROUBLESHOOTING|EXPECT|SPIN|CALC|CHALLENGE|SOLUTION)\s*:\s*(.*)$/.exec(text);
    if (flag) {
      openFlag = FLAG_KEYS[/** @type {keyof typeof FLAG_KEYS} */ (flag[1])];
      const body = (flag[2] ?? "").trim();
      // A solution answers the challenge before it (the Carpentries challenge with its nested solution), one each.
      if (openFlag === "solution" && flags.solution.length >= flags.challenge.length) {
        problems.push(`line ${line}: step ${number} has a SOLUTION with no CHALLENGE before it to answer`);
      }
      if (openFlag === "troubleshooting" || openFlag === "calc") {
        flags[openFlag].push(...body.split(/[,\s]+/).filter(Boolean));
      } else {
        flags[openFlag].push(body);
      }
      continue;
    }
    const more = /^>\s?(.*)$/.exec(text);
    if (more) {
      if (!openFlag || openFlag === "troubleshooting" || openFlag === "calc") {
        problems.push(`line ${line}: step ${number} has a quoted line that follows no flag: "${text.trim()}"`);
      } else {
        const list = flags[openFlag];
        list[list.length - 1] = `${list[list.length - 1] ?? ""}\n${more[1] ?? ""}`.replace(/^\n/, "");
      }
      continue;
    }
    openFlag = null;
    const photo = /^!\[([^\]]*)\]\(([^)\s]+)\)\s*$/.exec(text.trim());
    if (photo) {
      photos.push({ alt: photo[1] ?? "", src: photo[2] ?? "" });
      continue;
    }
    if (text.trim()) words.push(text.trim());
  }

  const source = words.join(" ");
  return {
    step: {
      number,
      line,
      source,
      segments: tokenize(source),
      flags: {
        ...flags,
        critical: flags.critical.map((s) => s.trim()),
        pause: flags.pause.map((s) => s.trim()),
        why: flags.why.map((s) => s.trim()),
        expect: flags.expect.map((s) => s.trim()),
        spin: flags.spin.map((s) => s.trim()),
        challenge: flags.challenge.map((s) => s.trim()),
        solution: flags.solution.map((s) => s.trim()),
      },
      commands,
      photos,
    },
    problems,
  };
}

/**
 * A section's lines as blocks: numbered items become steps; everything else at the margin is prose.
 *
 * @param {string[]} lines
 * @param {number} firstLine the file line of lines[0]
 * @returns {{ blocks: Block[], problems: string[] }}
 */
function readBlocks(lines, firstLine) {
  /** @type {Block[]} */
  const blocks = [];
  /** @type {string[]} */
  const problems = [];
  /** @type {string[]} */
  let prose = [];
  /** @type {Step[] | null} */
  let steps = null;
  let inFence = false;

  const flushProse = () => {
    const markdown = prose.join("\n").trim();
    if (markdown) blocks.push({ type: "prose", markdown });
    prose = [];
  };

  for (let i = 0; i < lines.length; i += 1) {
    const text = lines[i] ?? "";
    if (text.startsWith("```")) inFence = !inFence;
    const item = inFence ? null : /^(\d+)\.\s+(.*)$/.exec(text);
    if (!item) {
      if (steps && (text.trim() === "" || /^\s{2,}/.test(text))) {
        // A blank line inside a list is still the list, unless the margin comes next.
        const next = lines.slice(i + 1).find((l) => l.trim() !== "");
        if (text.trim() === "" && (next === undefined || !/^(\s{2,}|\d+\.\s)/.test(next))) steps = null;
        continue;
      }
      steps = null;
      prose.push(text);
      continue;
    }
    flushProse();
    const start = i;
    /** @type {string[]} */
    const rest = [];
    while (i + 1 < lines.length) {
      const next = lines[i + 1] ?? "";
      if (/^\s{2,}\S/.test(next)) rest.push(next.replace(/^\s{2,4}/, ""));
      else if (next.trim() === "" && /^\s{2,}\S/.test(lines[i + 2] ?? "")) rest.push("");
      else break;
      i += 1;
    }
    const read = readStep(item[2] ?? "", rest, firstLine + start, Number(item[1]));
    problems.push(...read.problems);
    if (!steps) {
      steps = [];
      blocks.push({ type: "steps", steps });
    }
    steps.push(read.step);
  }
  flushProse();
  return { blocks, problems };
}

/**
 * @param {{ file: string, raw: string }} input
 */
export function parseProcedure({ file, raw }) {
  /** @type {string[]} */
  const problems = [];
  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return {
      file,
      data: /** @type {Record<string, any>} */ ({}),
      intro: "",
      sections: /** @type {Section[]} */ ([]),
      problems: [`the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`],
    };
  }
  const data = /** @type {Record<string, any>} */ (plain(parsed.data));
  const headerLines = raw.slice(0, raw.length - parsed.content.length).split("\n").length - 1;
  const lines = parsed.content.split(/\r?\n/);

  /** @type {Section[]} */
  const sections = [];
  /** @type {string[]} */
  let intro = [];
  let current = /** @type {{ title: string, id: string, custom: boolean, line: number, lines: string[] } | null} */ (null);
  const close = () => {
    if (!current) return;
    const { blocks, problems: found } = readBlocks(current.lines, current.line + 1);
    problems.push(...found);
    sections.push({ title: current.title, id: current.id, custom: current.custom, line: current.line, blocks });
  };

  let inFence = false;
  lines.forEach((text, index) => {
    if (text.startsWith("```")) inFence = !inFence;
    const heading = inFence ? null : /^## (.+?)(?:\s+\{#([a-z0-9-]+)\})?\s*$/.exec(text);
    if (heading) {
      close();
      const title = (heading[1] ?? "").trim();
      current = { title, id: heading[2] ?? headingId(title), custom: Boolean(heading[2]), line: headerLines + index + 1, lines: [] };
      return;
    }
    if (current) current.lines.push(text);
    else intro.push(text);
  });
  close();

  // A step list before the first heading would have no section to belong to.
  if (intro.some((line) => /^\d+\.\s/.test(line))) {
    problems.push("the method starts before the first ## heading; put every step under a section");
  }

  return { file, data, intro: intro.join("\n").trim(), sections, problems };
}

/** @typedef {ReturnType<typeof parseProcedure>} ParsedProcedure */

/**
 * Every step in the procedure, in order.
 *
 * @param {ParsedProcedure} parsed
 */
export function allSteps(parsed) {
  return parsed.sections.flatMap((section) =>
    section.blocks.flatMap((block) => (block.type === "steps" ? block.steps : [])),
  );
}

/**
 * The calculators a step's CALC flag names, each with the values the step itself states for its fields:
 * `> CALC: webbed-plate volume=10, titer` is webbed-plate with volume 10, then titer. A `name=value` belongs
 * to the calculator before it; one with none before it is read as a calculator with no id, which validate.mjs refuses.
 *
 * @param {string[]} tokens the flag's words, as readStep split them
 * @returns {Array<{ id: string, values: Record<string, string> }>}
 */
export function readCalcs(tokens) {
  /** @type {Array<{ id: string, values: Record<string, string> }>} */
  const calcs = [];
  for (const token of tokens) {
    const eq = token.indexOf("=");
    if (eq === -1) {
      calcs.push({ id: token, values: {} });
      continue;
    }
    if (calcs.length === 0) calcs.push({ id: "", values: {} });
    /** @type {{ id: string, values: Record<string, string> }} */ (calcs[calcs.length - 1]).values[token.slice(0, eq)] = token.slice(eq + 1);
  }
  return calcs;
}

/**
 * A step's words with its marks read out, and the temperatures and spins those words state.
 *
 * @param {Step} step
 */
export function stepConditions(step) {
  return readConditions(step.segments.map((s) => segmentText(s)).join(""));
}

app/kb/procedures/validate.mjs.source:
// Judges a parsed procedure against its profile (docs/PROCEDURES.md). check:protocols and the operator
// API's save_procedure both call validateProcedure, so a file CI refuses is a file the save tool refuses,
// for the same reason in the same words.
//
// A value nobody has yet is written "MISSING: <why>" in place. It passes and is returned as a gap, so
// the check can print it and the read tool can show it. A bare MISSING, or a required field left out,
// is an error: a forgotten field cannot pass as a recorded gap.

import { DOI_PATTERN, VERSION_PATTERN } from "./cite.mjs";
import { allSteps, PLATFORMS, readCalcs, stepConditions } from "./parse.mjs";
import { proofErrors } from "./proof.mjs";
import { COURSES, METHODS, NON_STRAIN_ORGANISMS, PROTOCOL_STATUSES } from "./taxonomy.mjs";
import { TOOLS } from "../../lib/phage-tools.mjs";
import { BASES } from "../bases.mjs";

export const PROFILES = /** @type {const} */ (["protocol", "recipe", "computational"]);

/** Where each profile's pages live (its knowledge base's root, app/kb/bases.mjs); the file's name is the last segment. */
export const PROFILE_ROOTS = /** @type {Record<(typeof PROFILES)[number], string>} */ (
  Object.fromEntries(BASES.map((base) => [base.profile, base.entryRoot]))
);

export const NOT_APPLICABLE = "not applicable";

/** A software how-to's form, per Diátaxis (docs/KNOWLEDGE-BASE.md, S1): a lesson that teaches, or a recipe for a task. */
export const HOWTO_TYPES = /** @type {const} */ ({ tutorial: "Tutorial", "how-to": "How-to" });

/** The sentences a how-to's WHY may run to before its reasoning belongs on an explanation page it links (S1). */
export const HOWTO_WHY_SENTENCES = 3;

/** The sentences in some markdown: each run of words ended by ., ! or ? before a capital or the end, so "e.g. this" is one. @param {string} text */
export function sentenceCount(text) {
  return (text.replace(/`[^`]*`/g, "x").match(/[^.!?]*[A-Za-z0-9][^.!?]*[.!?]+(?=[*_]*(?:\s+[*_]*[A-Z0-9]|\s*$))/g) ?? []).length;
}

/** CLAUDE.md: "units are a closed list". A unit outside it fails until it is added here on purpose. */
export const PROTOCOL_UNITS = [
  "µl", "µL", "ml", "mL", "l", "L", "M", "mM", "µM", "nM", "mg/ml", "µg/ml", "ng/µl", "%", "U", "g", "mg", "µg", "ng",
  "volume", "volumes", "tube", "tubes", "reaction", "reactions", "plate", "plates", "x",
];
export const TIME_UNITS = ["second", "seconds", "sec", "s", "minute", "minutes", "min", "hour", "hours", "h", "day", "days"];

/** A recorded gap: the marker and the reason, never the marker alone. */
const GAP = /^MISSING:\s*(\S.*)$/s;

/** The levels a protocol's `biosafety_level` may name (CLAUDE.md); each is Dustin's to set. */
export const BIOSAFETY_LEVELS = ["BSL-1", "BSL-2"];

/** Words CLAUDE.md, keeps off a protocol's `biosafety` note: the agent only. The separate `biosafety_level` field holds the level. */
const BIOSAFETY_BANNED = /\b(BSL|biosafety level|IBC|NIH)\b/i;

/** A primer's id in the lab registry (app/kb/registry/compile.mjs ID_PATTERN): a protocol names primers by it and stores no sequence. */
const PRIMER_ID = /^[a-z0-9][a-z0-9-]{0,62}$/;

const SEO_TITLE_MAX = 60;
const DESCRIPTION_MAX = 155;

/**
 * @param {unknown} value
 */
function isGap(value) {
  return typeof value === "string" && GAP.test(value);
}

/**
 * @param {Record<string, unknown>} item
 * @param {number} index
 */
function label(item, index) {
  for (const key of ["id", "name", "set", "citation", "for"]) {
    if (typeof item[key] === "string" && item[key]) return /** @type {string} */ (item[key]);
  }
  return String(index);
}

/** What an item in a list is called in words: its name, stage or set, else its id. @param {Record<string, unknown>} item */
function itemName(item) {
  for (const key of ["name", "stage", "set", "id", "citation", "for"]) {
    if (typeof item[key] === "string" && item[key]) return /** @type {string} */ (item[key]);
  }
  return null;
}

/**
 * Every recorded gap under `value`, by path, with `where`: the same place in words, below the top-level field, so the
 * admin can say "TES buffer: storage" for solutions[tes-buffer].storage (app/kb/gap-labels.mjs). An unnamed item is its
 * place in its list ("step 2"), left out when it is the list's only item.
 *
 * @param {unknown} value
 * @param {string} path
 * @param {Array<{ field: string, reason: string, where?: string[] }>} gaps
 * @param {string[]} errors
 * @param {string[]} [where]
 * @param {string} [key] the key the value sits under
 */
function collectGaps(value, path, gaps, errors, where = [], key = "") {
  if (typeof value === "string") {
    const m = GAP.exec(value);
    if (m) gaps.push({ field: path, reason: (m[1] ?? "").trim(), ...(where.length > 0 ? { where } : {}) });
    else if (/^MISSING\b/.test(value)) errors.push(`${path} is "${value}": write MISSING: and the reason it is missing`);
  } else if (Array.isArray(value)) {
    value.forEach((item, i) => {
      const object = item && typeof item === "object" ? /** @type {Record<string, unknown>} */ (item) : null;
      const name = object ? itemName(object) : null;
      const words = name ? [...where, name] : value.length > 1 ? [...where, `${key.replace(/s$/, "")} ${i + 1}`] : where;
      collectGaps(item, `${path}[${object ? label(object, i) : i}]`, gaps, errors, words, key);
    });
  } else if (value && typeof value === "object") {
    for (const [k, v] of Object.entries(value)) {
      // A list or a group under a key is named by its items; a value is named by its key.
      const leaf = path && !(v && typeof v === "object");
      collectGaps(v, path ? `${path}.${k}` : k, gaps, errors, leaf ? [...where, k.replace(/_c$/, " (°C)").replaceAll("_", " ")] : where, k);
    }
  }
}

/**
 * "250 µl", "0.5 ml", "100% or 80%", "1.25 to 5 µl", "2.5 volumes".
 *
 * @param {string[]} units
 */
function quantityPattern(units) {
  const number = String.raw`\d[\d,]*(?:\.\d+)?`;
  const unit = units.map((u) => u.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")).join("|");
  return new RegExp(`^${number}(?: ?(?:${unit}))?(?: (?:to|or) ${number})? ?(?:${unit})$`);
}

const PROTOCOL_QUANTITY = quantityPattern(PROTOCOL_UNITS);

/**
 * @param {unknown} value
 */
function nonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

/**
 * The version history, newest first: each version with its date, what changed and, once Zenodo has minted
 * one, its DOI. The first entry is the version the page is at, so the version is stored once in `version`
 * and the history cannot disagree with it.
 *
 * @param {Record<string, any>} d
 * @param {string[]} errors
 */
function validateHistory(d, errors) {
  if (d.history === undefined || isGap(d.history)) return;
  if (!Array.isArray(d.history) || d.history.length === 0) {
    errors.push("history must be a list of versions, newest first");
    return;
  }
  const seen = new Set();
  let newer = "9999-12-31";
  d.history.forEach((/** @type {any} */ h, /** @type {number} */ i) => {
    const at = `history[${h?.version ?? i}]`;
    if (!h || typeof h !== "object") return errors.push(`${at} must be a version`);
    for (const k of Object.keys(h)) if (!["version", "date", "summary", "doi"].includes(k)) errors.push(`${at}.${k} is not a history field (version, date, summary, doi)`);
    if (!VERSION_PATTERN.test(String(h.version ?? ""))) errors.push(`${at} needs a version of letters, digits, dots, hyphens and underscores`);
    if (seen.has(String(h.version))) errors.push(`${at}: the version is listed twice`);
    seen.add(String(h.version));
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(h.date ?? ""))) errors.push(`${at}.date is ${JSON.stringify(h.date)}; write the date as YYYY-MM-DD`);
    else if (String(h.date) > newer) errors.push(`${at}.date ${h.date} is later than the entry above it; the history is newest first`);
    else newer = String(h.date);
    if (!nonEmptyString(h.summary)) errors.push(`${at} needs a summary of what changed`);
    if (h.doi !== undefined && !DOI_PATTERN.test(String(h.doi))) errors.push(`${at}.doi is ${JSON.stringify(h.doi)}; write the DOI as 10.xxxx/suffix, without the https://doi.org/ address`);
  });
  if (d.version === undefined || d.version === null || isGap(d.version)) {
    errors.push("history needs a version: the first entry is the version the page is at, so set version to it");
  } else if (String(d.history[0]?.version) !== String(d.version)) {
    errors.push(`version is ${JSON.stringify(d.version)} but the first history entry is ${JSON.stringify(String(d.history[0]?.version))}; the newest entry is the current version`);
  }
}

/**
 * Checks one parsed procedure.
 *
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 * @param {{ slug: string, primers?: ReadonlySet<string> | null, strains?: ReadonlySet<string> | null, reagents?: ReadonlySet<string> | null, equipment?: ReadonlySet<string> | null }} expect the slug its file name gives, and the ids of the primers and
 *   host strains the lab registry holds (null or absent when the registry is not at hand, which `compileProcedure` refuses for a protocol that lists primers)
 * @returns {{ errors: string[], gaps: Array<{ field: string, reason: string, where?: string[], section?: string }> }}
 */
export function validateProcedure(parsed, expect) {
  /** @type {string[]} */
  const errors = [...parsed.problems];
  /** @type {Array<{ field: string, reason: string, where?: string[], section?: string }>} */
  const gaps = [];
  const d = parsed.data;
  const profile = /** @type {typeof PROFILES[number]} */ (d.profile);

  if (!PROFILES.includes(profile)) {
    errors.push(`profile is ${JSON.stringify(d.profile)}; it must be one of ${PROFILES.join(", ")}`);
    return { errors, gaps };
  }

  /** @param {string} field */
  const required = (field) => {
    const value = d[field];
    if (value === undefined || value === null || value === "" || (Array.isArray(value) && value.length === 0)) {
      errors.push(`${field} is required for a ${profile}; write the value, or "MISSING: <why>" if nobody has it yet`);
      return false;
    }
    return true;
  };

  collectGaps(d, "", gaps, errors);

  // Identity.
  const root = PROFILE_ROOTS[profile];
  if (required("path")) {
    if (typeof d.path !== "string" || d.path !== `${root}${expect.slug}`) {
      errors.push(`path is ${JSON.stringify(d.path)}; a ${profile} named ${expect.slug}.md lives at ${root}${expect.slug}`);
    }
  }
  for (const field of ["title", "seo_title", "description"]) {
    if (required(field) && !nonEmptyString(d[field])) errors.push(`${field} must be text`);
  }
  if (typeof d.seo_title === "string" && d.seo_title.length > SEO_TITLE_MAX) {
    errors.push(`seo_title is ${d.seo_title.length} characters; Google clips near ${SEO_TITLE_MAX}`);
  }
  if (typeof d.description === "string" && d.description.length > DESCRIPTION_MAX) {
    errors.push(`description is ${d.description.length} characters; Google clips near ${DESCRIPTION_MAX}`);
  }
  if (d.draft !== undefined && typeof d.draft !== "boolean") errors.push("draft must be true or false");
  // A variant made with the editor's Duplicate names the procedure it was copied from, and the version it was copied at.
  if (d.forked_from !== undefined) {
    const f = d.forked_from;
    if (!f || typeof f !== "object" || Array.isArray(f) || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(String(f.slug ?? ""))) {
      errors.push("forked_from is { slug, version }: the file name of the procedure this one was copied from, and its version if it had one");
    } else {
      for (const key of Object.keys(f)) if (!["slug", "version"].includes(key)) errors.push(`forked_from.${key} is not a forked_from field (slug, version)`);
      if (f.slug === expect.slug) errors.push("forked_from names this procedure itself");
    }
  }

  // What the library filters by. method, organism and course are ids from the closed lists in taxonomy.mjs; target
  // is the gene, region or sample, in words. Every procedure is some method, so method is required.
  // An organism is a non-strain organism or a strain of the lab registry (docs/REGISTRY.md), read from it as the host strains are.
  const organisms = expect.strains ? [...Object.keys(NON_STRAIN_ORGANISMS), ...expect.strains] : null;
  for (const [field, vocabulary] of /** @type {const} */ ([["method", METHODS], ["organism", null], ["course", COURSES]])) {
    if (field === "method") required(field);
    const value = d[field];
    if (value === undefined || isGap(value)) continue;
    const allowed = vocabulary ? Object.keys(vocabulary) : organisms;
    // With no registry at hand an organism cannot be judged, and compileProcedure refuses a file that names one.
    if (!allowed) continue;
    if (!Array.isArray(value)) errors.push(`${field} must be a list of ids from: ${allowed.join(", ")}`);
    else {
      for (const id of value) {
        if (allowed.includes(id)) continue;
        errors.push(
          vocabulary
            ? `${field} "${id}" is not one of: ${allowed.join(", ")} (taxonomy.mjs)`
            : `organism "${id}" is neither one of: ${Object.keys(NON_STRAIN_ORGANISMS).join(", ")} (taxonomy.mjs) nor a strain in the lab registry (there is no content/registry/strain/${id}.md)`,
        );
      }
      if (new Set(value).size !== value.length) errors.push(`${field} names one id twice`);
    }
  }
  if (d.target !== undefined && !isGap(d.target)) {
    if (!Array.isArray(d.target) || d.target.some((t) => !nonEmptyString(t))) errors.push("target must be a list of the genes, regions or samples it works on, each in words");
  }

  // Where it stands in the library's "Start here" list: a position (1, 2, ...), stored, never inferred. A position
  // two procedures share would make the order a guess, so the corpus check refuses it (checkStartHere).
  if (d.start_here !== undefined && !isGap(d.start_here)) {
    if (!Number.isInteger(d.start_here) || d.start_here < 1) errors.push("start_here must be a position in the Start here list: 1, 2, 3 ...");
  }

  // Proof of use: the papers that used the method and the phages it produced, as slugs. Stated, never inferred.
  if (!isGap(d.proof_of_use)) errors.push(...proofErrors(d.proof_of_use));

  // The shared core.
  if (required("version") && !isGap(d.version) && !VERSION_PATTERN.test(String(d.version))) {
    errors.push(`version is ${JSON.stringify(d.version)}; it sits in a URL, so use letters, digits, dots, hyphens and underscores, such as "2" or "1.1"`);
  }
  validateHistory(d, errors);
  if (required("updated") && !isGap(d.updated) && !/^\d{4}-\d{2}-\d{2}$/.test(String(d.updated))) {
    errors.push(`updated is ${JSON.stringify(d.updated)}; write the date as YYYY-MM-DD`);
  }
  if (required("based_on") && !isGap(d.based_on)) {
    if (!Array.isArray(d.based_on)) errors.push("based_on must be a list of sources");
    else {
      d.based_on.forEach((/** @type {any} */ s, /** @type {number} */ i) => {
        if (!s || typeof s !== "object" || !nonEmptyString(s.citation)) errors.push(`based_on[${i}] needs a citation`);
        else if (!nonEmptyString(s.for)) errors.push(`based_on[${s.citation}] needs a "for": what it is the source of`);
      });
    }
  }
  if (required("references") && !isGap(d.references)) {
    if (!Array.isArray(d.references) || d.references.some((r) => !nonEmptyString(r))) {
      errors.push("references must be a list of markdown lines");
    }
  }
  for (const field of ["expected_results", "limitations"]) {
    if (required(field) && !nonEmptyString(d[field])) errors.push(`${field} must be markdown text`);
  }
  if (d.time !== undefined) {
    if (!d.time || typeof d.time !== "object") errors.push("time must hold total and hands_on");
    else for (const k of Object.keys(d.time)) if (!["total", "hands_on"].includes(k)) errors.push(`time.${k} is not a time field`);
  }

  // Materials and equipment.
  /** @type {Map<string, any>} */
  const materials = new Map();
  if (profile !== "recipe" || d.materials !== undefined) {
    if (required("materials")) {
      if (!Array.isArray(d.materials)) errors.push("materials must be a list");
      else {
        d.materials.forEach((/** @type {any} */ m, /** @type {number} */ i) => {
          if (!m || typeof m !== "object" || !nonEmptyString(m.name)) {
            errors.push(`materials[${i}] needs a name`);
            return;
          }
          const key = m.name.toLowerCase();
          if (materials.has(key)) errors.push(`materials lists "${m.name}" twice`);
          materials.set(key, m);
        });
      }
    }
  }
  if (d.equipment !== undefined && !Array.isArray(d.equipment)) errors.push("equipment must be a list");
  // An item that is lab-registry equipment names it with `equipment: <id>` (docs/REGISTRY.md): the protocol keeps its own phrase for
  // it (the setting is the protocol's), and who makes it is stored there once.
  if (Array.isArray(d.equipment)) {
    for (const e of d.equipment) {
      if (typeof e !== "object" || e === null || e.equipment === undefined) continue;
      const at = `equipment[${String(e.name)}]`;
      if (typeof e.equipment !== "string" || !PRIMER_ID.test(e.equipment)) {
        errors.push(`${at}.equipment is the id of an equipment item in the lab registry (content/registry/equipment/), such as water-bath`);
      } else if (expect.equipment && !expect.equipment.has(e.equipment)) {
        errors.push(`${at}.equipment names no equipment in the lab registry (there is no content/registry/equipment/${e.equipment}.md)`);
      }
    }
  }
  const equipmentNames = new Set(
    (Array.isArray(d.equipment) ? d.equipment : []).map((/** @type {any} */ e) =>
      String(typeof e === "string" ? e : e?.name ?? "").toLowerCase(),
    ),
  );

  // Troubleshooting.
  const troubleIds = new Set();
  if (d.troubleshooting !== undefined) {
    if (!Array.isArray(d.troubleshooting)) errors.push("troubleshooting must be a list of rows");
    else {
      d.troubleshooting.forEach((/** @type {any} */ row, /** @type {number} */ i) => {
        const at = `troubleshooting[${row?.id ?? i}]`;
        if (!row || typeof row !== "object") return errors.push(`${at} must be a row`);
        if (!/^[a-z0-9-]+$/.test(String(row.id ?? ""))) errors.push(`${at} needs an id in lowercase-with-hyphens`);
        if (troubleIds.has(row.id)) errors.push(`${at}: the id is used twice`);
        troubleIds.add(row.id);
        for (const col of ["step", "problem", "reason", "solution"]) {
          if (!nonEmptyString(row[col])) errors.push(`${at} needs ${col}: the table's columns are step, problem, possible reason, solution`);
        }
        for (const k of Object.keys(row)) {
          if (!["id", "step", "problem", "reason", "solution"].includes(k)) errors.push(`${at}.${k} is not a column`);
        }
      });
    }
  }

  // The method.
  const steps = allSteps(parsed);
  if (steps.length === 0) errors.push("the procedure has no steps: a method section holds a numbered list");
  let previous = 0;
  for (const section of parsed.sections) {
    for (const block of section.blocks) {
      if (block.type !== "steps") continue;
      const first = block.steps[0];
      if (first && first.number !== 1 && first.number !== previous + 1) {
        errors.push(`line ${first.line}: step ${first.number} neither restarts at 1 nor follows step ${previous}`);
      }
      block.steps.forEach((step, i) => {
        if (i > 0 && step.number !== (block.steps[i - 1]?.number ?? 0) + 1) {
          errors.push(`line ${step.line}: step ${step.number} follows step ${block.steps[i - 1]?.number}`);
        }
      });
      previous = block.steps[block.steps.length - 1]?.number ?? previous;
    }
  }

  // A step's section, so a gap in it can say where it is (app/kb/gap-labels.mjs).
  const sectionOf = new Map(parsed.sections.flatMap((section) => section.blocks.flatMap((block) => (block.type === "steps" ? block.steps.map((s) => [s, section.title]) : []))));
  for (const step of steps) {
    const at = `line ${step.line}, step ${step.number}`;
    if (!step.source.trim()) errors.push(`${at} has no words`);
    for (const reason of step.flags.critical) if (!reason) errors.push(`${at}: CRITICAL needs its reason`);
    for (const kind of /** @type {const} */ (["pause", "why", "expect", "challenge", "solution"])) {
      for (const text of step.flags[kind]) if (!text) errors.push(`${at}: an empty ${kind.toUpperCase()} flag`);
    }
    for (const id of step.flags.troubleshooting) {
      if (!troubleIds.has(id)) errors.push(`${at}: TROUBLESHOOTING names "${id}", which is not a row id in troubleshooting`);
    }
    if (step.flags.calc.length > 0 && profile !== "protocol") errors.push(`${at}: CALC belongs to the protocol profile`);
    const calcs = readCalcs(step.flags.calc);
    if (new Set(calcs.map((c) => c.id)).size !== calcs.length) errors.push(`${at}: CALC names a calculator twice`);
    for (const { id, values } of calcs) {
      const tool = Object.hasOwn(TOOLS, id) ? TOOLS[id] : undefined;
      if (!tool) {
        errors.push(id ? `${at}: CALC names "${id}", which is not a calculator (${Object.keys(TOOLS).join(", ")})` : `${at}: CALC gives a value before it names a calculator`);
        continue;
      }
      for (const [name, value] of Object.entries(values)) {
        if (!tool.fields.some((f) => f.name === name)) errors.push(`${at}: CALC ${id} has no field "${name}" (${tool.fields.map((f) => f.name).join(", ")})`);
        // Every value is the step's own: a number that is not in the step's words is not from the record.
        else if (!step.source.includes(value)) errors.push(`${at}: CALC ${id} ${name}=${value}, but the step does not state ${value}; a value is filled in only from the step's own words`);
      }
    }
    for (const seg of step.segments) {
      if (seg.type === "material") {
        const declared = materials.get(seg.name.toLowerCase());
        if (!declared && profile !== "recipe") {
          errors.push(`${at}: @${seg.name} is not in materials; declare it there with its stock and amount`);
        }
        if (seg.quantity && profile === "protocol" && !PROTOCOL_QUANTITY.test(`${seg.quantity.amount} ${seg.quantity.unit}`.trim())) {
          errors.push(`${at}: @${seg.name}'s amount "${seg.quantity.raw}" is not a number and a unit from the closed list (${PROTOCOL_UNITS.join(", ")})`);
        }
      }
      if (seg.type === "equipment" && profile !== "recipe" && !equipmentNames.has(seg.name.toLowerCase())) {
        errors.push(`${at}: #${seg.name} is not in equipment`);
      }
      if (seg.type === "timer") {
        if (!seg.quantity || seg.quantity.min === null || !TIME_UNITS.includes(seg.quantity.unit)) {
          errors.push(`${at}: the timer ~{${seg.quantity?.raw ?? ""}} needs a number and a unit of time (${TIME_UNITS.join(", ")})`);
        }
      }
    }
    if (profile === "protocol") {
      const { spins } = stepConditions(step);
      const words = step.segments.map((s) => (s.type === "text" ? s.value : "")).join("");
      const spinsHere = /\bspin\b|\bspun\b|\bcentrifuge\b/i.test(words.replace(/pulse[- ]spin/gi, ""));
      const hasG = spins.some((s) => s.unit === "x g");
      if (spinsHere && !hasG && step.flags.spin.length === 0) {
        errors.push(`${at} spins with no g-force: add "> SPIN: <n> x g", or "> SPIN: MISSING: <why>" (a speed in rpm needs the rotor)`);
      }
      for (const spin of step.flags.spin) {
        if (isGap(spin)) gaps.push({ field: `step ${step.number} (line ${step.line}).spin`, reason: spin.replace(/^MISSING:\s*/, ""), section: sectionOf.get(step) ?? "" });
        else if (!/x g\b/.test(spin)) errors.push(`${at}: SPIN "${spin}" is not in x g`);
      }
    } else if (step.flags.spin.length > 0) {
      errors.push(`${at}: SPIN belongs to the protocol profile`);
    }
    // A tutorial teaches with challenges; a how-to links its reasoning out (S1, S5).
    if (step.flags.challenge.length > 0 && !(profile === "computational" && d.type === "tutorial")) {
      errors.push(`${at}: CHALLENGE belongs to a tutorial (a computational procedure with type: tutorial)`);
    }
    if (step.flags.solution.length < step.flags.challenge.length) errors.push(`${at}: each CHALLENGE needs its SOLUTION after it`);
    if (profile === "computational" && d.type === "how-to") {
      for (const why of step.flags.why) {
        const n = sentenceCount(why);
        if (n > HOWTO_WHY_SENTENCES) {
          errors.push(`${at}: WHY runs to ${n} sentences; a how-to keeps a reason to ${HOWTO_WHY_SENTENCES} at most, so put the rest on a page and link it under explanation`);
        }
      }
    }
    /** @type {Set<string>} */
    const platforms = new Set();
    for (const cmd of step.commands) {
      if (cmd.platform === null) continue;
      if (profile !== "computational") errors.push(`${at}: platform= belongs to the computational profile`);
      else if (!Object.hasOwn(PLATFORMS, cmd.platform)) errors.push(`${at}: platform=${cmd.platform} is not a platform (${Object.keys(PLATFORMS).join(", ")})`);
      else if (platforms.has(cmd.platform)) errors.push(`${at}: two blocks for platform=${cmd.platform}; a step gives each platform one block`);
      platforms.add(cmd.platform);
    }
    if (platforms.size === 1) errors.push(`${at}: a block names one platform alone; give each platform its block, or name none`);
    if (profile === "computational") {
      for (const cmd of step.commands) {
        if (cmd.output === null && step.flags.expect.length === 0) {
          errors.push(`${at}: a command needs its expected output: a \`\`\`output block after it, or an EXPECT flag`);
        }
      }
    } else if (step.commands.length > 0 && profile === "recipe") {
      errors.push(`${at}: a recipe step carries no commands`);
    }
    if (step.photos.length > 0 && profile !== "recipe") errors.push(`${at}: step photos belong to the recipe profile`);
    for (const photo of step.photos) if (!photo.alt.trim()) errors.push(`${at}: a step photo needs its alt text`);
  }

  // The profiles.
  // A recipe's density, so its volume can be shown as weight: a number the recipe states, never a table's (DECIDE 7).
  for (const m of Array.isArray(d.materials) ? d.materials : []) {
    if (m?.grams_per_cup === undefined) continue;
    const at = `materials[${String(m.name)}].grams_per_cup`;
    if (profile !== "recipe") errors.push(`${at} belongs to the recipe profile`);
    else if (typeof m.grams_per_cup !== "number" || !(m.grams_per_cup > 0)) errors.push(`${at} is the grams in one US cup of it, a number above 0`);
  }
  if (profile === "protocol") protocolRules(d, errors, required, materials, expect.primers ?? null, expect.strains ?? null, expect.reagents ?? null);
  if (profile === "recipe") recipeRules(d, errors, required);
  if (profile === "computational") computationalRules(d, errors, required, materials);
  else {
    for (const field of ["type", "questions", "objectives", "key_points", "explanation"]) {
      if (d[field] !== undefined) errors.push(`${field} belongs to the computational profile`);
    }
  }

  return { errors, gaps };
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 * @param {Map<string, any>} materials
 * @param {ReadonlySet<string> | null} primerIds the primers the lab registry holds
 * @param {ReadonlySet<string> | null} strainIds the strains the lab registry holds
 * @param {ReadonlySet<string> | null} reagentIds the reagents the lab registry holds
 */
function protocolRules(d, errors, required, materials, primerIds, strainIds, reagentIds) {
  for (const field of ["host_strain", "status", "last_run", "biosafety", "biosafety_level", "scale"]) required(field);
  // A host strain is the lab registry's, named by id and never typed (docs/REGISTRY.md): its organism, designation and
  // collection number are stored once, on its record.
  if (d.host_strain !== undefined && d.host_strain !== NOT_APPLICABLE && !isGap(d.host_strain)) {
    if (!Array.isArray(d.host_strain)) errors.push(`host_strain must be a list of { strain: <id> }, "${NOT_APPLICABLE}" or "MISSING: <why>"`);
    else {
      /** @type {Set<string>} */
      const seenStrains = new Set();
      for (const s of d.host_strain) {
        const id = s?.strain;
        const at = `host_strain[${typeof id === "string" ? id : "?"}]`;
        if (typeof id !== "string" || !PRIMER_ID.test(id)) {
          errors.push(`${at} is { strain: <id> }: the id of a strain in the lab registry (content/registry/strain/), such as foliorum. A protocol names its host strains and types none`);
        } else if (seenStrains.has(id)) {
          errors.push(`${at} is listed twice`);
        } else {
          seenStrains.add(id);
          if (strainIds && !strainIds.has(id)) errors.push(`${at} names no strain in the lab registry (there is no content/registry/strain/${id}.md)`);
        }
        for (const key of Object.keys(s ?? {})) {
          if (key !== "strain") errors.push(`${at}.${key} is not a protocol field: a strain's organism and collection number are stored once, in the lab registry`);
        }
      }
    }
  }
  if (d.status !== undefined && !isGap(d.status) && !Object.keys(PROTOCOL_STATUSES).includes(d.status)) {
    errors.push(`status is ${JSON.stringify(d.status)}; it is one of ${Object.keys(PROTOCOL_STATUSES).join(", ")} (taxonomy.mjs), or "MISSING: <why>"`);
  }
  if (d.biosafety_level !== undefined && !isGap(d.biosafety_level) && !BIOSAFETY_LEVELS.includes(d.biosafety_level)) {
    errors.push(`biosafety_level is ${JSON.stringify(d.biosafety_level)}; it is one of ${BIOSAFETY_LEVELS.join(", ")}, or "MISSING: <why>" until Dustin sets it`);
  }
  if (d.biosafety && !isGap(d.biosafety) && d.biosafety !== NOT_APPLICABLE) {
    if (typeof d.biosafety !== "object" || !nonEmptyString(d.biosafety.organism)) {
      errors.push('biosafety lists the agent only: { organism, strain, atcc }, or "not applicable"');
    } else {
      for (const k of Object.keys(d.biosafety)) {
        if (!["organism", "strain", "atcc"].includes(k)) errors.push(`biosafety.${k}: the agent only (organism, strain, ATCC number) (CLAUDE.md)`);
      }
    }
  }
  if (BIOSAFETY_BANNED.test(JSON.stringify(d.biosafety ?? ""))) {
    errors.push("biosafety names a biosafety level, an IBC or the NIH Guidelines; it lists the agent only (CLAUDE.md)");
  }
  if (d.scale && !isGap(d.scale)) {
    if (typeof d.scale !== "object" || !(Number(d.scale.count) > 0) || !nonEmptyString(d.scale.unit)) {
      errors.push("scale needs a count and a unit, such as { count: 5, unit: tube }");
    }
  }
  const solutionIds = new Set();
  if (d.solutions !== undefined) {
    if (!Array.isArray(d.solutions)) errors.push("solutions must be a list");
    else {
      for (const s of d.solutions) {
        const at = `solutions[${s?.id ?? "?"}]`;
        if (!s || !/^[a-z0-9-]+$/.test(String(s.id ?? ""))) errors.push(`${at} needs an id in lowercase-with-hyphens`);
        solutionIds.add(s?.id);
        if (!nonEmptyString(s?.name)) errors.push(`${at} needs a name`);
        if (!Array.isArray(s?.components) || s.components.length === 0) errors.push(`${at} needs its components`);
        for (const field of ["storage", "shelf_life"]) {
          if (!nonEmptyString(s?.[field])) errors.push(`${at} needs ${field}, or "MISSING: <why>"`);
        }
        for (const c of Array.isArray(s?.components) ? s.components : []) {
          if (!nonEmptyString(c?.name)) errors.push(`${at} has a component with no name`);
          for (const q of ["final", "amount"]) {
            if (c?.[q] !== undefined && !isGap(c[q]) && !PROTOCOL_QUANTITY.test(String(c[q]))) {
              errors.push(`${at}.${c.name}.${q} is "${c[q]}", not a number and a unit from the closed list`);
            }
          }
        }
      }
    }
  }
  for (const m of materials.values()) {
    const at = `materials[${m.name}]`;
    // A material that is a reagent of the lab registry names it by id (docs/REGISTRY.md): who supplies it and its catalog number
    // are stored there once, and the protocol keeps its own amount, stock and final.
    if (m.reagent !== undefined) {
      if (typeof m.reagent !== "string" || !PRIMER_ID.test(m.reagent)) {
        errors.push(`${at}.reagent is the id of a reagent in the lab registry (content/registry/reagent/), such as zinc-chloride`);
      } else if (reagentIds && !reagentIds.has(m.reagent)) {
        errors.push(`${at}.reagent names no reagent in the lab registry (there is no content/registry/reagent/${m.reagent}.md)`);
      }
    }
    for (const key of ["amount", "final", "per"]) {
      const q = m[key];
      if (q === undefined || isGap(q)) continue;
      if (key === "per" && typeof q === "string" && !/^\d/.test(q)) continue;
      if (typeof q !== "string" || !PROTOCOL_QUANTITY.test(q)) {
        errors.push(`${at}.${key} is "${String(q)}", not a number and a unit from the closed list (${PROTOCOL_UNITS.join(", ")})`);
      }
    }
    if (m.stock !== undefined) {
      const stocks = Array.isArray(m.stock) ? m.stock : [m.stock];
      for (const s of stocks) {
        if (!isGap(s) && !PROTOCOL_QUANTITY.test(String(s))) errors.push(`${at}.stock "${s}" is not a number and a unit from the closed list`);
      }
    }
    if (m.solution !== undefined && !solutionIds.has(m.solution)) errors.push(`${at}.solution names "${m.solution}", which is not in solutions`);
  }
  if (d.primers !== undefined && d.primers !== NOT_APPLICABLE && !isGap(d.primers)) {
    if (!Array.isArray(d.primers)) errors.push(`primers must be a list, or "${NOT_APPLICABLE}"`);
    else {
      /** @type {Set<string>} */
      const seen = new Set();
      for (const p of d.primers) {
        const id = p?.primer;
        const at = `primers[${typeof id === "string" ? id : "?"}]`;
        if (typeof id !== "string" || !PRIMER_ID.test(id)) {
          errors.push(`${at} is { primer: <id> }: the id of a primer in the lab registry (content/registry/primer/), such as lco1490. A protocol names its primers and stores no sequence`);
        } else if (seen.has(id)) {
          errors.push(`${at} is listed twice`);
        } else {
          seen.add(id);
          if (primerIds && !primerIds.has(id)) errors.push(`${at} names no primer in the lab registry (there is no content/registry/primer/${id}.md)`);
        }
        for (const key of Object.keys(p ?? {})) {
          if (key !== "primer") errors.push(`${at}.${key} is not a protocol field: a primer's sequence, direction and set are stored once, in the lab registry`);
        }
      }
    }
  }
  if (d.cycling !== undefined) {
    if (!Array.isArray(d.cycling)) errors.push("cycling must be a list of programs");
    else {
      const walk = (/** @type {any} */ stage, /** @type {string} */ at) => {
        if (Array.isArray(stage?.steps)) stage.steps.forEach((/** @type {any} */ s, /** @type {number} */ i) => walk(s, `${at}.steps[${i}]`));
        if (typeof stage?.temperature_c === "string" && /^\d+ to \d+$/.test(stage.temperature_c) && stage.touchdown_step_c === undefined) {
          errors.push(`${at} is a touchdown (${stage.temperature_c} °C) with no touchdown_step_c; write it, or "MISSING: <why>"`);
        }
      };
      d.cycling.forEach((/** @type {any} */ program, /** @type {number} */ i) => {
        const at = `cycling[${program?.set ?? i}]`;
        if (!Array.isArray(program?.program)) errors.push(`${at} needs its program: a list of stages`);
        else program.program.forEach((/** @type {any} */ stage, /** @type {number} */ j) => walk(stage, `${at}.program[${stage?.stage ?? j}]`));
      });
    }
  }
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 */
function recipeRules(d, errors, required) {
  for (const field of ["servings", "cuisine", "category", "prep_time", "cook_time", "image"]) required(field);
  if (d.servings !== undefined && !isGap(d.servings) && !(Number(d.servings) > 0)) errors.push("servings must be a number");
  for (const field of ["prep_time", "cook_time"]) {
    if (d[field] !== undefined && !isGap(d[field]) && !/^\d+(?:\.\d+)? (minutes?|hours?)$/.test(String(d[field]))) {
      errors.push(`${field} is "${d[field]}"; write it as "20 minutes" or "1.5 hours"`);
    }
  }
  if (d.image !== undefined && !isGap(d.image) && (!nonEmptyString(d.image?.src) || !nonEmptyString(d.image?.alt))) {
    errors.push("image needs src and alt");
  }
  if (d.substitutions !== undefined) {
    if (!Array.isArray(d.substitutions)) errors.push("substitutions must be a list");
    else for (const s of d.substitutions) if (!nonEmptyString(s?.for) || !nonEmptyString(s?.use)) errors.push("each substitution needs for and use");
  }
  if (d.scale !== undefined) errors.push("a recipe scales by servings, not scale");
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 * @param {Map<string, any>} materials
 */
function computationalRules(d, errors, required, materials) {
  required("environment");
  if (required("type") && !Object.hasOwn(HOWTO_TYPES, d.type)) {
    errors.push(`type is ${JSON.stringify(d.type)}; it is one of ${Object.keys(HOWTO_TYPES).join(", ")}`);
  }
  // A tutorial opens as a Carpentries episode does: what it answers, what the reader will be able to do, and how long (S2).
  for (const field of ["questions", "objectives", "key_points"]) {
    if (d[field] === undefined || isGap(d[field])) continue;
    if (!Array.isArray(d[field]) || d[field].some((/** @type {unknown} */ x) => !nonEmptyString(x))) errors.push(`${field} must be a list of lines`);
  }
  if (d.type === "tutorial") {
    required("objectives");
    if (!d.time || !nonEmptyString(d.time.total)) errors.push("a tutorial states its time: time.total, such as 30 minutes");
  }
  if (d.explanation !== undefined && !isGap(d.explanation)) {
    if (!Array.isArray(d.explanation)) errors.push("explanation must be a list of pages, each with a title and a url");
    else {
      d.explanation.forEach((/** @type {any} */ e, /** @type {number} */ i) => {
        if (!e || typeof e !== "object" || !nonEmptyString(e.title)) errors.push(`explanation[${i}] needs a title`);
        else if (typeof e.url !== "string" || !/^(\/[^/\s]|https:\/\/\S)/.test(e.url)) errors.push(`explanation[${e.title}].url is a page on this site (/...) or an https address`);
      });
    }
  }
  if (required("prerequisites") && !isGap(d.prerequisites) && !Array.isArray(d.prerequisites)) {
    errors.push("prerequisites must be a list");
  }
  if (d.scale !== undefined || d.servings !== undefined) errors.push("a computational procedure does not scale");
  for (const m of materials.values()) {
    if (!["software", "data", "file"].includes(m.kind)) errors.push(`materials[${m.name}].kind must be software, data or file`);
    if (m.kind === "software" && !nonEmptyString(m.version)) errors.push(`materials[${m.name}] is software and needs its version`);
  }
}

app/kb/registry/primer.mjs.source:
// The primer kind of the lab registry (docs/REGISTRY.md). A primer record states what the lab's protocols state about one
// oligo (its sequence as stored, its direction, the set it works in and what that set targets) and what the literature says
// about it, as read: the paper that prints it, that paper's own name for it, the sequence the paper prints, the product size
// the paper states, and the reference sequence the primer is placed on.
//
// Anything not stored is COMPUTED and so cannot drift: its length, GC content, Tm and reverse complement come from the
// sequence (tm.mjs, primers.mjs); its position, strand and mismatches on the reference, and a pair's product, come from the
// reference by tested code (align.mjs); whether the stored sequence matches the printed one is a comparison, not a field; and
// the protocols that use it are found from the protocols, which name their primers by id.
//
// A fact nobody could read is written "MISSING: <why>" with the reason (paywalled, not stated), never filled from memory or
// inferred. A sequence that DIFFERS from the one a paper prints is shown as differing on its page and listed by
// check:content; it is never corrected silently, and the decision to change it is the seat's.

import { REFERENCES } from "./references.generated.mjs";
import { primerTmRounded } from "./tm.mjs";

/** An upper-case IUPAC nucleotide sequence, as the protocols write one. */
const SEQUENCE = /^[ACGTRYSWKMBDHVN]+$/;
export const PRIMER_MIN_LENGTH = 10;
export const PRIMER_MAX_LENGTH = 80;
export const DIRECTIONS = /** @type {const} */ (["forward", "reverse", "probe"]);
/** A product as a paper states it: a size in base pairs, "about" when the paper says so. */
const PRODUCT = /^(?:about )?[1-9][0-9]{1,4} bp$/;
const DOI = /^10\.[0-9]{4,9}\/[^\s]+$/;
const LINE = /^[^\r\n]+$/;

/** @param {unknown} value @param {number} max */
const oneLine = (value, max) =>
  typeof value === "string" && LINE.test(value) && value === value.trim() && value.length <= max ? null : `is one line of at most ${max} characters`;

/** @param {unknown} value */
const sequenceCheck = (value) =>
  typeof value !== "string" || !SEQUENCE.test(value)
    ? "is an upper-case IUPAC nucleotide sequence, written 5' to 3'"
    : value.length < PRIMER_MIN_LENGTH || value.length > PRIMER_MAX_LENGTH
      ? `is ${PRIMER_MIN_LENGTH} to ${PRIMER_MAX_LENGTH} bases`
      : null;

/** @type {import("./kinds.mjs").KindSpec} */
export const PRIMER = {
  singular: "primer",
  plural: "primers",
  fields: {
    sequence: { required: true, check: sequenceCheck },
    direction: {
      required: true,
      check: (value) => (DIRECTIONS.includes(/** @type {any} */ (value)) ? null : `is ${DIRECTIONS.join(", ")} or MISSING`),
    },
    target: { required: true, check: (value) => oneLine(value, 120) },
    set: { check: (value) => oneLine(value, 120) },
    // The reference the primer is placed on: a file in data/references (docs/REGISTRY.md), named by its GenBank id.
    reference: {
      check: (value) =>
        typeof value === "string" && Object.hasOwn(REFERENCES, value)
          ? null
          : `is the id of a reference in data/references: ${Object.keys(REFERENCES).join(", ")}`,
    },
    // The literature, as read. Each is the paper's own words or MISSING with the reason it could not be read.
    published_in: { required: true, check: (value) => oneLine(value, 200) },
    published_doi: { check: (value) => (typeof value === "string" && DOI.test(value) ? null : "is a DOI, such as 10.1371/journal.pone.0099678") },
    published_url: { check: (value) => (typeof value === "string" && /^https:\/\/[^\s]+$/.test(value) ? null : "is an https address") },
    published_name: { required: true, check: (value) => oneLine(value, 120) },
    published_sequence: { required: true, check: sequenceCheck },
    // The product size the paper states for the pair, on the forward primer only: a size is a pair's, and it is shown beside the
    // computed one, never in its place.
    published_product: {
      check: (value) => (typeof value === "string" && PRODUCT.test(value) ? null : 'is a size as the paper states it, such as "710 bp" or "about 710 bp"'),
    },
  },
  /**
   * What only the whole set can say: a sequence is stored once (two records cannot hold it), a set holds at most one forward and
   * one reverse primer, a published product is stated on the forward primer alone, and a pair shares one reference, because a
   * pair's product is computed on one sequence.
   */
  setErrors(items) {
    /** @type {string[]} */
    const errors = [];
    /** @type {Map<string, string>} */
    const sequences = new Map();
    /** @type {Map<string, { forward: string[], reverse: string[], references: Set<string> }>} */
    const sets = new Map();
    for (const { id, fields } of items) {
      const sequence = String(fields.sequence);
      const other = sequences.get(sequence);
      if (!sequence.startsWith("MISSING")) {
        if (other !== undefined) errors.push(`primer/${id} and primer/${other} hold the same sequence; a sequence is stored once`);
        else sequences.set(sequence, id);
      }
      const set = typeof fields.set === "string" ? fields.set : null;
      if (set !== null) {
        const entry = sets.get(set) ?? { forward: [], reverse: [], references: new Set() };
        if (fields.direction === "forward") entry.forward.push(id);
        if (fields.direction === "reverse") entry.reverse.push(id);
        if (typeof fields.reference === "string" && !fields.reference.startsWith("MISSING")) entry.references.add(fields.reference);
        sets.set(set, entry);
      }
      const product = fields.published_product;
      if (typeof product === "string" && !product.startsWith("MISSING") && fields.direction !== "forward") {
        errors.push(`primer/${id} states a published product, but a product is a pair's and is stated on its forward primer`);
      }
    }
    for (const [set, { forward, reverse, references }] of sets) {
      if (forward.length > 1) errors.push(`the set "${set}" has ${forward.length} forward primers (${forward.join(", ")}); a set has one`);
      if (reverse.length > 1) errors.push(`the set "${set}" has ${reverse.length} reverse primers (${reverse.join(", ")}); a set has one`);
      if (references.size > 1) errors.push(`the set "${set}" names ${references.size} references (${[...references].join(", ")}); a pair is placed on one`);
    }
    return errors;
  },
};

/**
 * What a primer's page and rows derive from its sequence alone: its length, GC content and Tm, and null where the sequence is
 * not one the model applies to (a gap, or an ambiguity code).
 *
 * @param {string} sequence
 */
export function primerFacts(sequence) {
  if (!/^[ACGT]+$/.test(sequence)) return { length: /^[A-Z]+$/.test(sequence) ? sequence.length : null, gcPercent: null, tm: null };
  const gc = [...sequence].filter((base) => base === "G" || base === "C").length;
  return { length: sequence.length, gcPercent: Math.round((gc / sequence.length) * 1000) / 10, tm: primerTmRounded(sequence) };
}

/** A field as text: a recorded gap (MISSING: why) and an absent value are both nothing to show. @param {unknown} value */
export function stated(value) {
  return typeof value === "string" && value !== "" && !value.startsWith("MISSING") ? value : null;
}

/** The reason a field is missing, or null when it is stated or absent. @param {unknown} value */
export function missingReason(value) {
  return typeof value === "string" && value.startsWith("MISSING:") ? value.replace(/^MISSING:\s*/, "") : null;
}

/**
 * A primer as a protocol carries it (`StoredPrimer` in app/kb/procedures/render.mjs): the registry's stated facts, none
 * computed. The protocol's record holds these so its page, sheet, twin and frozen versions print one sequence, and a pair's
 * product is computed from them where it is shown.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {import("../procedures/render.mjs").StoredPrimer}
 */
export function storedPrimer(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return {
    id: item.id,
    name: item.name,
    status: item.status,
    set: stated(f.set),
    direction: stated(f.direction),
    sequence: stated(f.sequence),
    reference: stated(f.reference),
    // The paper that prints it, for a protocol's Key Resources Table; null where the registry records a gap.
    publishedIn: stated(f.published_in),
  };
}

app/lib/backup/policy.mjs.source:
// PURE on purpose, like verdicts.mjs: check:tests cannot reach a module that imports a binding, and
// the rules that decide whether a dump may be marked complete must be provable by `node --test`.

/**
 * The D1 tables that are NOT derived from the repository or the bucket (hard rule 18), so the dump
 * is the only copy of their rows. Read off drizzle/*.sql on 2026-10-11; the reason names the source
 * of each. Every other table converges toward the repository or a bucket and is repaired through
 * its derivation, so its absence from a dump would cost a rebuild, not data.
 *
 * `settings` is not here: its one key, llms.txt, is derived from the repository by sync_llms.
 */
export const NON_DERIVED_TABLES = Object.freeze({
  webmentions: "rows came from strangers' POSTs and the moderation decisions on them (migration 0014)",
  zero_result_queries: "search demand signal, swept by retention, converges toward nothing (0015)",
  procedure_versions: "the sealed frozen copy of every published procedure version, never rewritten (0027)",
  kb_locations: "Knowledge Base inventory locations, written through site-api (0029)",
  kb_lots: "Knowledge Base inventory lots, written through site-api (0029)",
  kb_audit: "the audit trail of the two inventory tables (0029)",
  members: "lab members and their titles (0030)",
  member_audit: "the audit trail of membership changes (0030)",
  member_terms: "lab term end dates (0030)",
});

/** A dump that lacks any of these is not complete, whatever else it holds. */
export const REQUIRED_TABLES = Object.freeze(Object.keys(NON_DERIVED_TABLES));

/**
 * Tables left out of the dump because they hold live credentials or one-time tokens. EMPTY, and
 * deliberately so: no table in the current schema holds either. The Better Auth tables (user,
 * session, account, verification) were dropped by migration 0026, admin sign-in is Cloudflare
 * Access and keeps no row, and preview-link tokens live in KV (app/lib/preview-token.mjs), not D1.
 * A table added later that matches CREDENTIAL_COLUMN fails the dump by name until it is listed
 * here, with the reason, or its column is renamed.
 */
/** @type {readonly string[]} */
export const EXCLUDED_TABLES = Object.freeze(/** @type {string[]} */ ([]));

/** A column name that says it holds a credential. Matched case-insensitively, camelCase included. */
export const CREDENTIAL_COLUMN = /password|passwd|secret|token|api_?key|credential|private_?key/i;

/**
 * @param {string} sql a CREATE TABLE statement
 * @returns {string[]} the column names it declares
 */
export function columnNames(sql) {
  const open = sql.indexOf("(");
  const close = sql.lastIndexOf(")");
  if (open < 0 || close < open) return [];
  const body = sql.slice(open + 1, close);
  const parts = [];
  let depth = 0;
  let current = "";
  for (const ch of body) {
    if (ch === "(") depth += 1;
    if (ch === ")") depth -= 1;
    if (ch === "," && depth === 0) {
      parts.push(current);
      current = "";
    } else current += ch;
  }
  parts.push(current);
  const names = [];
  for (const part of parts) {
    const text = part.trim();
    if (!text || /^(constraint|primary|unique|foreign|check)\b/i.test(text)) continue;
    const match = /^(?:"([^"]+)"|`([^`]+)`|\[([^\]]+)\]|(\S+))/.exec(text);
    const name = match?.[1] ?? match?.[2] ?? match?.[3] ?? match?.[4];
    if (name) names.push(name);
  }
  return names;
}

/**
 * Every problem that stops a dump being marked complete, each naming the table. An empty list is
 * the only pass; the caller refuses the marker otherwise and throws, so the run stays incomplete.
 *
 * @param {{
 *   tables: Array<{ name: string, rows: number }>,
 *   excluded: string[],
 *   schema: Array<{ type: string, name: string, sql: string }>,
 * }} dump what dumpDatabase returned, and the CREATE statements of the database it read
 * @param {{ required?: readonly string[], allowedExcluded?: readonly string[] }} [policy]
 * @returns {string[]}
 */
export function dumpProblems(dump, policy = {}) {
  const required = policy.required ?? REQUIRED_TABLES;
  const allowedExcluded = policy.allowedExcluded ?? EXCLUDED_TABLES;
  const problems = [];

  const held = new Map(dump.tables.map((t) => [t.name, t.rows]));
  const total = [...held.values()].reduce((sum, rows) => sum + rows, 0);
  if (held.size === 0 || total === 0) {
    problems.push(`the dump holds no rows (${held.size} table(s), ${total} row(s)), which is what a wrong or emptied database looks like`);
  }

  for (const name of required) {
    if (!held.has(name)) problems.push(`required table ${name} is missing from the dump`);
  }

  for (const name of dump.excluded) {
    if (!allowedExcluded.includes(name)) problems.push(`table ${name} was excluded but is not on the excluded list, so its rows would be lost silently`);
  }

  for (const entry of dump.schema) {
    if (entry.type !== "table" || /^\s*CREATE\s+VIRTUAL/i.test(entry.sql)) continue;
    if (dump.excluded.includes(entry.name)) continue;
    if (!held.has(entry.name)) continue;
    const credential = columnNames(entry.sql).filter((c) => CREDENTIAL_COLUMN.test(c));
    if (credential.length > 0) {
      problems.push(`table ${entry.name} has credential-looking column(s) ${credential.join(", ")} and is in the dump; exclude it with a reason or rename the column`);
    }
  }
  return problems;
}

