// The one judgement of content/llms.txt, shared by check:machine-readable (scripts/machine-readable/llms.mjs)
// and the save (app/lib/llms/save.server.ts), so a file CI passes is the file a save accepts
// (docs/LLMS.md). Pure: the caller supplies what the file is judged against.

/** The repository file, which is the source (hard rule 18). */
export const LLMS_PATH = "content/llms.txt";

/** The `settings` row /llms.txt is served from: derived from the file, never edited by hand. */
export const LLMS_SETTING_KEY = "llms.txt";

/** Every /llms.txt response carries it, and a save purges it (app/routes/llms.ts). */
export const LLMS_CACHE_TAG = "llms";

/** The file's whole size, far above today's and far below anything a crawler would read to the end. */
export const LLMS_MAX_BYTES = 65_536;

/** A file shorter than this is the retired 247-byte virology seed, not the real document. */
const LLMS_MIN_BYTES = 200;

/**
 * What the file must document, as the exact text an agent is told. Each is a URL pattern or a header an
 * agent acts on, so a rewrite that drops one has taken a capability away from every agent that read it.
 */
export const LLMS_REQUIRED_MENTIONS = [
  "/llms-full.txt",
  "/writing/rss.xml",
  "/writing/feed.json",
  "/writing/<slug>.md",
  "Accept: text/markdown",
  "/research/publications/<doi-slug>/",
  "/research/publications/<doi-slug>.md",
  "/research/publications.bib",
  "/research/publications.ris",
  "/research/publications.json",
  "/colophon",
];

/*
 * The llmstxt.org shape: a page is a list item whose link carries an absolute URL, `- [Title](https://host/path): note`.
 * The collection hub /research/publications and the lab registry under /research/lab are routes and not content pages, so
 * they are not read as ones.
 */
const LISTED_PAGE =
  /^- \[[^\]]+\]\(https?:\/\/[^/\s)]+(?!\/research\/(?:publications|lab)\b)(\/(?:research|teaching|software|cv|privacy|terms|accessibility)(?:\/[a-z0-9-]+)*)\)/gm;
const LISTED_TWIN = /^- \[[^\]]+\]\(https?:\/\/[^/\s)]+(\/research\/publications\/[a-z0-9-]+\.md)\)/gm;

/** The page paths the file lists, one per list link. @param {string} text */
function listedPagePaths(text) {
  return new Set([...text.matchAll(LISTED_PAGE)].map((m) => m[1] ?? ""));
}

/** The paper twin URLs the file lists, as paths, one per list link. @param {string} text */
export function listedPaperTwins(text) {
  return new Set([...text.matchAll(LISTED_TWIN)].map((m) => m[1] ?? ""));
}

/**
 * Listed twins no paper produces: the one rule check:machine-readable's twin gate and a save share. A paper
 * added later is not in the list until it is written there, so the reverse is not a rule.
 *
 * @param {string} text
 * @param {Iterable<string>} twinUrls the `/research/publications/<slug>.md` URLs the corpus produces
 */
export function overAdvertisedTwins(text, twinUrls) {
  const known = new Set(twinUrls);
  return [...listedPaperTwins(text)].filter((url) => !known.has(url));
}

/**
 * @typedef {{ name: string, ok: boolean, detail?: string }} LlmsCheck
 *
 * @param {string} text the whole file
 * @param {{
 *   pagePaths: readonly string[],
 *   origin: string,
 *   findWideDashes: (text: string) => Array<{ line: number, char: string, excerpt: string }>,
 *   twinUrls?: Iterable<string>,
 *   optionalPagePaths?: readonly string[],
 * }} options pagePaths is every Research, Teaching and Software path a reader can open, the procedures'
 *   included, and the file must list each; optionalPagePaths are registered pages that are drafts, which the
 *   file may list (so its line can land before the page is published) but need not; twinUrls is every paper
 *   twin the corpus produces, left out where the corpus is judged elsewhere
 * @returns {LlmsCheck[]} every rule, passed or failed, in the order they read
 */
export function llmsChecks(text, { pagePaths, origin, findWideDashes, twinUrls, optionalPagePaths = [] }) {
  /** @type {LlmsCheck[]} */
  const checks = [];
  /** @param {string} name @param {boolean} ok @param {string} [detail] */
  const check = (name, ok, detail) => checks.push({ name, ok, detail: ok ? undefined : detail });

  const bytes = new TextEncoder().encode(text).length;
  check("llms.txt is not empty", bytes > 0, "the file is empty");
  check(
    "llms.txt is long enough to be the real document",
    bytes > LLMS_MIN_BYTES,
    `Only ${bytes} bytes. The retired virology seed was 247 bytes; the real document is far longer, so a ` +
      "short file here is the stale copy.",
  );
  check(
    `llms.txt is at most ${LLMS_MAX_BYTES} bytes`,
    bytes <= LLMS_MAX_BYTES,
    `${bytes} bytes. An agent reads this file first and whole; a file this long is no longer a map.`,
  );
  check(
    "llms.txt is LF-only",
    !text.includes("\r"),
    "It is pinned to LF in .gitattributes. CR here would sync CRLF into D1.",
  );
  check("llms.txt ends with a newline", text.endsWith("\n"), "the last byte is not a newline");
  check(
    "llms.txt opens with its H1 title",
    text.startsWith("# dustinedwards.info\n"),
    'the first line must be "# dustinedwards.info", as agents read the first heading as the site name',
  );

  // What PageSpeed's agent-discoverability audit reads: the summary, and links it can follow.
  check(
    "llms.txt has a blockquote summary under its title",
    /^# [^\n]+\n\n> \S/.test(text),
    'the llmstxt.org format puts a "> summary" line after the H1 and one blank line',
  );
  const relative = [...text.matchAll(/\]\((\/[^)\s]*)\)/g)].map((m) => m[1]);
  check(
    "every markdown link in llms.txt is absolute",
    relative.length === 0,
    `relative link(s): ${relative.slice(0, 5).join(", ")}. A crawler reading the file alone has no origin to resolve them against.`,
  );

  const dashes = findWideDashes(text);
  check(
    "llms.txt has no wide dash",
    dashes.length === 0,
    dashes
      .slice(0, 5)
      .map((d) => `line ${d.line} ${d.char}: ${d.excerpt}`)
      .join("; ") + "; use a comma, period, parentheses or colon",
  );

  const missing = LLMS_REQUIRED_MENTIONS.filter((mention) => !text.includes(mention));
  check(
    `llms.txt documents the ${LLMS_REQUIRED_MENTIONS.length} URL patterns and headers an agent acts on`,
    missing.length === 0,
    `absent: ${missing.join(", ")}`,
  );

  // Both ways, derived from the list the routes and the sitemap read: a page missing here is a page an
  // agent is not told about, twin or not.
  const listed = listedPagePaths(text);
  const unlisted = pagePaths.filter((path) => !listed.has(path));
  check(
    `llms.txt lists every Research, Teaching and Software page (${pagePaths.length})`,
    unlisted.length === 0,
    `absent from ${LLMS_PATH}: ${unlisted.join(", ")}`,
  );
  const known = new Set([...pagePaths, ...optionalPagePaths]);
  const stray = [...listed].filter((path) => !known.has(path));
  check(
    "llms.txt lists no Research, Teaching or Software page that is neither in CONTENT_PAGE_PATHS nor a procedure",
    stray.length === 0,
    `listed but not a page: ${stray.join(", ")}`,
  );

  if (twinUrls) {
    const over = overAdvertisedTwins(text, twinUrls);
    check(
      "llms.txt lists no paper twin the corpus does not produce",
      over.length === 0,
      `advertised with no paper: ${over.join(", ")}`,
    );
  }

  // A tracked text file cannot import SITE_ORIGIN, so this binds its contact line to it. At DNS cutover
  // it goes red until llms.txt follows, which is the point.
  const contact = (text.match(/## Contact\s*\n\s*\n(?:- \[[^\]]*\]\()?(https?:\/\/[^\s)]+)/) ?? [])[1] ?? "";
  check(
    "llms.txt has a contact URL to compare",
    contact.startsWith("https://"),
    `parsed ${JSON.stringify(contact)} from the Contact section`,
  );
  check(
    "the llms.txt contact URL is SITE_ORIGIN",
    contact === origin,
    `llms.txt says ${contact} and SITE_ORIGIN is ${origin}. The file crawlers read points somewhere this ` +
      "site is not served from.",
  );

  return checks;
}

/**
 * The messages of every failed rule, or an empty list: what a save refuses with.
 *
 * @param {LlmsCheck[]} checks
 */
export function llmsErrors(checks) {
  return checks.filter((c) => !c.ok).map((c) => `${c.name}: ${c.detail}`);
}

app/lib/media/tile-nav.mjs.source:
/**
 * The media grid's arrow-key geometry, pure so it can be tested without a DOM. Rows come from
 * rendered boxes, not a column model: the browser decides the column count, and a second layout
 * engine would disagree with it at the widths nobody tested.
 */

/** @typedef {{ id: string, top: number, left: number, width: number }} TileBox */
/** @typedef {{ top: number, items: Array<{ id: string, mid: number }> }} Band */
/** @typedef {"left" | "right" | "up" | "down"} Direction */

/**
 * Visual rows, from the rendered boxes. Tiles within 6px share a row. A box with no width is not
 * laid out (a hidden tile) and joins no row.
 *
 * @param {Iterable<TileBox>} boxes
 * @returns {Band[]}
 */
export function bands(boxes) {
  /** @type {Band[]} */
  const out = [];
  for (const r of boxes) {
    if (!r.width) continue;
    const entry = { id: r.id, mid: r.left + r.width / 2 };
    const band = out.find((b) => Math.abs(b.top - r.top) < 6);
    if (band) band.items.push(entry);
    else out.push({ top: r.top, items: [entry] });
  }
  out.sort((a, b) => a.top - b.top);
  for (const b of out) b.items.sort((x, y) => x.mid - y.mid);
  return out;
}

/**
 * The tile an arrow key moves to, or null to stay put. With nothing active, or an active id that is
 * no longer on the page, the first tile. Left and right wrap across rows in reading order; up and
 * down take the nearest tile by centre in the next row, and stop at the edges.
 *
 * @param {Band[]} rows
 * @param {string} active
 * @param {Direction} dir
 * @returns {string | null}
 */
export function nextTile(rows, active, dir) {
  const flat = rows.flatMap((b) => b.items.map((i) => i.id));
  const firstId = flat[0];
  if (firstId === undefined) return null;
  if (!active) return firstId;

  let ri = -1;
  let ci = -1;
  rows.forEach((b, i) =>
    b.items.forEach((it, j) => {
      if (it.id === active) {
        ri = i;
        ci = j;
      }
    }),
  );
  if (ri < 0) return firstId;
  const row = rows[ri];
  const current = row?.items[ci];
  if (!row || !current) return null;
  if (dir === "left" || dir === "right") {
    const next = row.items[ci + (dir === "right" ? 1 : -1)];
    if (next) return next.id;
    const k = flat.indexOf(active) + (dir === "right" ? 1 : -1);
    return flat[k] || null;
  }
  const band = rows[ri + (dir === "down" ? 1 : -1)];
  if (!band) return null;
  const mid = current.mid;
  let best = band.items[0];
  if (!best) return null;
  let bestD = Infinity;
  for (const it of band.items) {
    const d = Math.abs(it.mid - mid);
    if (d < bestD) {
      bestD = d;
      best = it;
    }
  }
  return best.id;
}

/**
 * Which tile's controls are in the tab order: the one last focused, else the one the inspector is
 * open on, else the first. One tile only, so Tab crosses the whole grid in that tile's few controls.
 *
 * @param {string[]} visible the keys on this page, in document order
 * @param {string} active the tile focus was last on, or ""
 * @param {string} inspected the key the inspector is open on, or ""
 * @returns {string} the key, or "" on an empty page
 */
export function rovingKey(visible, active, inspected) {
  if (active && visible.includes(active)) return active;
  if (inspected && visible.includes(inspected)) return inspected;
  return visible[0] ?? "";
}

app/lib/not-found-query.mjs.source:
// Plain .mjs so `node --test` can import it; the types are JSDoc under checkJs.

/**
 * The words of a missing address, to start the 404 page's search box with: the last path segment
 * with any file extension off, split on everything that is not a letter or digit. Number-only words
 * are dropped, because a bare year is a search filter and an old dated address would otherwise
 * narrow the search to that year. Percent escapes are dropped rather than decoded, since a malformed
 * one would throw. Empty when nothing useful is left, and the box then shows its placeholder.
 *
 * @param {string} pathname
 * @returns {string}
 */
export function notFoundQuery(pathname) {
  const segments = pathname.split("/").filter((segment) => segment.length > 0);
  const last = segments.at(-1) ?? "";
  const words = last
    .replace(/%[0-9A-Fa-f]{2}/g, " ")
    .replace(/\.[A-Za-z0-9]{1,5}$/, "")
    .split(/[^\p{L}\p{N}]+/u)
    .filter((word) => word.length > 0 && !/^\p{N}+$/u.test(word));
  return words.join(" ").slice(0, 100).trim();
}

app/lib/phage-tools.mjs.source:
/**
 * The phage lab calculators at /research/tools: titer, serial dilution, webbed plate, MOI, efficiency of
 * plating and lysate volume. One pure module,
 * imported by the server-rendered calculator (app/components/phage-tool.tsx), which renders the worked
 * example with script off, and by the browser module that recomputes on input (app/enhance/tools.ts).
 * test/phage-tools.test.mjs holds it against hand arithmetic and the numbers on the FAQ and the
 * isolation protocol, and holds each page's worked example to what this module prints.
 *
 * Every lab default here names the page that states it (`source`), and the page shows that source.
 * Volumes are in µl and titers in pfu/ml throughout, as on the FAQ.
 */

/** @typedef {{ href: string, label: string }} Source */

/**
 * @typedef {object} ToolField
 * @property {string} name the query parameter and the input's name
 * @property {string} label
 * @property {string} [unit]
 * @property {string} value the value the page opens with
 * @property {string} [hint]
 * @property {Source} [source] set when `value` is a lab default rather than the worked example's number
 */

/** @typedef {{ text: string, sup?: false } | { text: string, sup: true }} TextPart */

/**
 * @typedef {object} ToolSection
 * @property {string} heading
 * @property {string[]} steps the arithmetic, one line each, in the order it is done
 * @property {string} [result] the answer, set apart from the steps
 * @property {string[]} [notes] cautions from the lab's pages, shown after the steps
 */

/** @typedef {{ ok: true, sections: ToolSection[] } | { ok: false, error: string }} ToolResult */

const FAQ = "/teaching/virus-isolation/faq";
const PROTOCOL = "/research/protocols/phage-isolation";

/** @type {Record<string, Source>} */
export const SOURCES = {
  fullPlate: { href: `${PROTOCOL}#full-plate-titer`, label: "Phage Isolation and Purification Protocol: full plate titer" },
  spot: { href: `${PROTOCOL}#spot-titer`, label: "Phage Isolation and Purification Protocol: spot titer" },
  tenfold: { href: FAQ, label: "Lab Calculations and Common Questions: 10-fold serial dilution" },
  volumeLimit: { href: `${PROTOCOL}#the-bracketing-shortcut`, label: "Phage Isolation and Purification Protocol: volume limit" },
  yields: { href: `${PROTOCOL}#yields`, label: "Phage Isolation and Purification Protocol: yields" },
};

/** The lab's numbers, each with its page. Nothing here is a value no page states. */
export const LAB = {
  /** Full plate titer: 10 µl of each dilution with 250 µl host. */
  ulPlated: 10,
  /** Spot titer: the Guide's Protocol 6.4, 3 µl spots, as the lab runs it. */
  ulSpot: 3,
  /** A 10-fold step: 10 µl phage + 90 µl phage buffer. */
  transferUl: 10,
  /** No more lysate than 10% of the 250 µl of host, or the cells lyse. */
  maxLysateUl: 25,
  /** Each plate flooded with 8 ml of phage buffer returns about 5 to 7 ml. */
  floodMl: 8,
  yieldLowMl: 5,
  yieldHighMl: 7,
  /** Plan about 6 webbed plates for 10 ml to archive plus 10 ml for DNA extraction. */
  plates: 6,
};

/* ---------------------------------------------------------------- numbers */

/**
 * A number as the bench writes it: `1.1e10`, `1.1 x 10^10`, `1.1×10^10`, `11,100` or `10^-3`.
 * Returns NaN for anything else, including an empty field, so the caller names the field.
 *
 * @param {unknown} raw
 */
export function parseNumber(raw) {
  const text = String(raw ?? "")
    .trim()
    .replace(/[\s,]/g, "")
    .replace(/[×xX*]/g, "x")
    .replace(/−/g, "-");
  if (text === "") return Number.NaN;
  const sci = /^([+-]?\d*\.?\d+)x10\^([+-]?\d+)$/.exec(text);
  if (sci) return Number(sci[1]) * 10 ** Number(sci[2]);
  const power = /^10\^([+-]?\d+)$/.exec(text);
  if (power) return 10 ** Number(power[1]);
  if (!/^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i.test(text)) return Number.NaN;
  return Number(text);
}

/** @param {number} value @param {number} digits */
function roundSig(value, digits) {
  if (value === 0 || !Number.isFinite(value)) return value;
  return Number(value.toPrecision(digits));
}

/** Trailing zeros off a fixed-point string: 1.50 to 1.5, 2.00 to 2. @param {string} text */
function trim(text) {
  return text.includes(".") ? text.replace(/0+$/, "").replace(/\.$/, "") : text;
}

/**
 * Three significant figures, never more than the value has. Plain with thousands separators from 0.01
 * up to a million, and `a x 10^n` outside that, the way the FAQ writes titers.
 *
 * @param {number} value
 */
export function formatNumber(value) {
  if (!Number.isFinite(value)) return String(value);
  if (value === 0) return "0";
  const rounded = roundSig(value, 3);
  const abs = Math.abs(rounded);
  if (abs >= 0.01 && abs < 1e6) {
    const [whole = "", fraction] = trim(String(rounded)).split(".");
    const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return fraction ? `${grouped}.${fraction}` : grouped;
  }
  return formatScientific(rounded);
}

/** Always `a x 10^n`, three significant figures: 1.11 x 10^10, 1 x 10^-3. @param {number} value */
export function formatScientific(value) {
  if (value === 0) return "0";
  const [mantissa = "", exponent] = roundSig(value, 3).toExponential(2).split("e");
  return `${trim(mantissa)} x 10^${Number(exponent)}`;
}

/** `10^-6`, and `undiluted` for 10^0. @param {number} n */
export function formatDilution(n) {
  return n === 0 ? "undiluted" : `10^-${n}`;
}

/**
 * A line split into plain runs and superscripts, so both renderers show `10^6` as 10 with a raised 6
 * and neither parses markup.
 *
 * @param {string} line
 * @returns {TextPart[]}
 */
export function textParts(line) {
  /** @type {TextPart[]} */
  const parts = [];
  let last = 0;
  for (const match of line.matchAll(/10\^(-?\d+)/g)) {
    const at = match.index ?? 0;
    parts.push({ text: `${line.slice(last, at)}10` });
    parts.push({ text: (match[1] ?? "").replace("-", "−"), sup: true });
    last = at + match[0].length;
  }
  parts.push({ text: line.slice(last) });
  return parts.filter((part) => part.text !== "");
}

/**
 * A value the arithmetic guarantees, checked anyway: an index past the end is a bug here, not input.
 *
 * @template T
 * @param {T | undefined} value
 * @returns {T}
 */
function must(value) {
  if (value === undefined) throw new Error("phage-tools: a planned step is missing.");
  return value;
}

const WORDS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
/** @param {number} n */
function count(n) {
  return WORDS[n] ?? String(n);
}

/* ---------------------------------------------------------------- titer */

/**
 * titer (pfu/ml) = plaques counted / µl plated x 1,000 µl/ml x dilution factor, the FAQ's formula.
 * A spot titer is the same with the spot volume.
 *
 * @param {{ plaques: number, volumeUl: number, dilutionExponent: number }} input
 */
export function titer({ plaques, volumeUl, dilutionExponent }) {
  const perUl = plaques / volumeUl;
  const perMlDiluted = perUl * 1000;
  const pfuPerMl = perMlDiluted * 10 ** dilutionExponent;
  return { perUl, perMlDiluted, pfuPerMl };
}

/**
 * A plaque count, the volume plated and the dilution's exponent, read and checked. Shared by the titer
 * calculator and the EOP-from-counts calculator, so both refuse the same inputs in the same words.
 * `where` names the plate in the message ("" for one plate, " on the test host" for EOP).
 *
 * @param {unknown} rawPlaques @param {unknown} rawVolume @param {unknown} rawDilution @param {string} [where]
 * @returns {{ ok: true, plaques: number, volumeUl: number, n: number } | { ok: false, error: string }}
 */
function readCount(rawPlaques, rawVolume, rawDilution, where = "") {
  const plaques = parseNumber(rawPlaques);
  const volumeUl = parseNumber(rawVolume);
  const rawN = parseNumber(rawDilution);
  if (!Number.isFinite(plaques) || plaques < 0 || !Number.isInteger(plaques)) {
    return { ok: false, error: `Enter the plaques counted${where} as a whole number, 0 or more.` };
  }
  if (!Number.isFinite(volumeUl) || volumeUl <= 0) {
    return { ok: false, error: `Enter the volume plated or spotted${where}, in µl, greater than 0.` };
  }
  // A dilution is never more than 1, so 6 and -6 both mean 10^-6.
  const n = Math.abs(rawN);
  if (!Number.isFinite(rawN) || !Number.isInteger(n) || n > 20) {
    return { ok: false, error: `Enter the dilution's exponent${where} as a whole number from 0 to 20: 6 for 10^-6, 0 if undiluted.` };
  }
  return { ok: true, plaques, volumeUl, n };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runTiter(values) {
  const read = readCount(values.plaques, values.volume, values.dilution);
  if (!read.ok) return read;
  const { plaques, volumeUl, n } = read;
  const { perUl, perMlDiluted, pfuPerMl } = titer({ plaques, volumeUl, dilutionExponent: n });
  const of = n === 0 ? "in the undiluted lysate" : `in the ${formatDilution(n)} dilution`;
  const steps = [
    `Plaques per µl: ${formatNumber(plaques)} / ${formatNumber(volumeUl)} µl = ${formatNumber(perUl)} pfu/µl.`,
    `Per ml: ${formatNumber(perUl)} x 1,000 = ${formatNumber(perMlDiluted)} pfu/ml ${of}.`,
  ];
  if (n > 0) {
    steps.push(`Undo the dilution: ${formatNumber(perMlDiluted)} x 10^${n} = ${formatScientific(pfuPerMl)} pfu/ml.`);
  }
  /** @type {string[]} */
  const notes = [];
  if (plaques === 0) {
    notes.push("No plaques: the titer is below what this plate can measure. Count a less dilute plate.");
  } else {
    const log = Math.log10(perUl);
    const exponent = Math.floor(log + 3 + n + 1e-9);
    steps.push(
      `Check the exponent: log10(${formatNumber(perUl)}) + 3 + ${n} = ${log.toFixed(2)} + 3 + ${n} = ${(log + 3 + n).toFixed(2)}, so the titer is in the 10^${exponent} range.`,
    );
  }
  return {
    ok: true,
    sections: [{ heading: "Titer", steps, result: `${formatScientific(pfuPerMl)} pfu/ml`, notes }],
  };
}

/* ---------------------------------------------------------------- dilution */

/**
 * @typedef {object} DilutionStep
 * @property {number} tube 1-based
 * @property {number} transferUl from the tube before (tube 1 takes from the lysate)
 * @property {number} bufferUl
 * @property {number} fold this step's own dilution
 * @property {number} cumulativeFold from the lysate to this tube
 * @property {number} pfuPerMl in this tube
 */

/**
 * The tubes that take a lysate from `startPfuPerMl` down to `targetPfuPerMl`: as many 10-fold steps as
 * fit (transfer + 9 x transfer of buffer), then one smaller step for whatever is left over when the
 * total is not a power of ten. Volumes are rounded to 0.1 µl and the tube concentrations are computed
 * from the rounded volumes, so they are what the tubes will hold. When `neededUl` is set, the last tube
 * holds at least that much, and each tube before it at least what the next one takes.
 *
 * @param {{ startPfuPerMl: number, targetPfuPerMl: number, transferUl?: number, neededUl?: number }} input
 */
export function planDilution({ startPfuPerMl, targetPfuPerMl, transferUl = LAB.transferUl, neededUl = 0 }) {
  const totalFold = startPfuPerMl / targetPfuPerMl;
  const tenfold = Math.floor(Math.log10(totalFold) + 1e-9);
  const remainder = totalFold / 10 ** tenfold;
  /** @type {number[]} */
  const folds = Array.from({ length: tenfold }, () => 10);
  // A remainder within 1% of 1 is a power of ten that floating point missed by a hair.
  if (remainder > 1.01) folds.push(remainder);

  const round = (/** @type {number} */ v) => Math.round(v * 10) / 10;
  // From the last tube back: each tube must hold what the next one takes, and the last what is needed.
  /** @type {number[]} */
  const totals = Array.from({ length: folds.length }, () => 0);
  // Filled from the end, so each tube's total is known before the tube that supplies it.
  let required = neededUl;
  for (let i = folds.length - 1; i >= 0; i -= 1) {
    const fold = must(folds[i]);
    // Never a volume under 1 µl: a 1.05-fold step at 10 µl would need 0.5 µl of buffer.
    const smallest = Math.max(fold, fold / (fold - 1));
    const total = Math.max(transferUl * fold, smallest, required);
    totals[i] = total;
    required = total / fold;
  }

  /** @type {DilutionStep[]} */
  const steps = [];
  let cumulativeFold = 1;
  folds.forEach((fold, i) => {
    const total = must(totals[i]);
    const transfer = round(total / fold);
    const buffer = round(total - total / fold);
    const actualFold = (transfer + buffer) / transfer;
    cumulativeFold *= actualFold;
    steps.push({
      tube: i + 1,
      transferUl: transfer,
      bufferUl: buffer,
      fold: actualFold,
      cumulativeFold,
      pfuPerMl: startPfuPerMl / cumulativeFold,
    });
  });
  return { totalFold, tenfold, remainder, steps, finalPfuPerMl: startPfuPerMl / cumulativeFold };
}

/** @param {DilutionStep} step @param {number} tenfoldCount */
function stepLine(step, tenfoldCount) {
  const from = step.tube === 1 ? "lysate" : `tube ${step.tube - 1}`;
  const label = step.tube <= tenfoldCount ? formatDilution(step.tube) : `1/${formatNumber(step.cumulativeFold)}`;
  return `Tube ${step.tube}: ${formatNumber(step.transferUl)} µl ${from} + ${formatNumber(step.bufferUl)} µl phage buffer = ${label}, ${formatScientific(step.pfuPerMl)} pfu/ml.`;
}

/**
 * The steps shared by the dilution and webbed-plate calculators: the fold, how it splits, the tubes.
 *
 * @param {ReturnType<typeof planDilution>} plan
 * @param {number} startPfuPerMl
 * @param {number} targetPfuPerMl
 */
function planLines(plan, startPfuPerMl, targetPfuPerMl) {
  const lines = [
    `Total dilution: ${formatScientific(startPfuPerMl)} / ${formatScientific(targetPfuPerMl)} = ${formatNumber(plan.totalFold)}-fold.`,
  ];
  const split =
    plan.steps.length === plan.tenfold
      ? `That is 10^${plan.tenfold}: ${count(plan.tenfold)} 10-fold steps.`
      : plan.tenfold === 0
        ? `That is less than 10-fold: one ${formatNumber(plan.remainder)}-fold step.`
        : `That is 10^${plan.tenfold} x ${formatNumber(plan.remainder)}: ${count(plan.tenfold)} 10-fold ${plan.tenfold === 1 ? "step" : "steps"}, then one ${formatNumber(plan.remainder)}-fold step.`;
  lines.push(split);
  for (const step of plan.steps) lines.push(stepLine(step, plan.tenfold));
  return lines;
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runDilution(values) {
  const start = parseNumber(values.start);
  const target = parseNumber(values.target);
  const transfer = parseNumber(values.transfer);
  const needed = values.needed === undefined || String(values.needed).trim() === "" ? 0 : parseNumber(values.needed);
  if (!Number.isFinite(start) || start <= 0) return { ok: false, error: "Enter the starting titer in pfu/ml, greater than 0." };
  if (!Number.isFinite(target) || target <= 0) return { ok: false, error: "Enter the target concentration in pfu/ml, greater than 0." };
  if (target >= start) return { ok: false, error: "The target is not below the starting titer, so there is nothing to dilute." };
  if (start / target > 1e20) return { ok: false, error: "That is more than 20 10-fold steps. Check the exponents." };
  if (!Number.isFinite(transfer) || transfer <= 0) return { ok: false, error: "Enter the volume carried into each tube, in µl, greater than 0." };
  if (!Number.isFinite(needed) || needed < 0) return { ok: false, error: "Enter the volume needed from the last tube in µl, or leave it empty." };
  const plan = planDilution({ startPfuPerMl: start, targetPfuPerMl: target, transferUl: transfer, neededUl: needed });
  const steps = planLines(plan, start, target);
  const last = must(plan.steps.at(-1));
  const lastVolume = last.transferUl + last.bufferUl;
  if (needed > 0) steps.push(`The last tube holds ${formatNumber(lastVolume)} µl, enough for the ${formatNumber(needed)} µl needed.`);
  /** @type {string[]} */
  const notes = [];
  if (plan.steps.some((step) => step.transferUl < 1 || step.bufferUl < 1)) {
    notes.push("A volume is under 1 µl. Raise the volume carried into each tube so every volume can be pipetted.");
  }
  return {
    ok: true,
    sections: [
      {
        heading: "Dilution series",
        steps,
        result: `${plan.steps.length} ${plan.steps.length === 1 ? "tube" : "tubes"}, ending at ${formatScientific(plan.finalPfuPerMl)} pfu/ml`,
        notes,
      },
    ],
  };
}

/* ---------------------------------------------------------------- webbed plate */

/**
 * µl of lysate per plate = pfu wanted per plate / titer (pfu/ml) x 1,000 µl/ml, the FAQ's formula.
 *
 * @param {{ titerPfuPerMl: number, pfuPerPlate: number }} input
 */
export function lysatePerPlate({ titerPfuPerMl, pfuPerPlate }) {
  return (pfuPerPlate / titerPfuPerMl) * 1000;
}

/**
 * Lysate back from flooding: plates x the lab's 5 to 7 ml per plate.
 *
 * @param {{ plates: number, lowMl?: number, highMl?: number }} input
 */
export function floodYield({ plates, lowMl = LAB.yieldLowMl, highMl = LAB.yieldHighMl }) {
  return { lowMl: plates * lowMl, highMl: plates * highMl };
}

/**
 * Plates to flood for a lysate volume: ml wanted / 5 to 7 ml per plate, rounded up. Fewest plates at
 * the high yield, most at the low one.
 *
 * @param {{ mlWanted: number, lowMl?: number, highMl?: number }} input
 */
export function platesForLysate({ mlWanted, lowMl = LAB.yieldLowMl, highMl = LAB.yieldHighMl }) {
  return { fewest: Math.ceil(mlWanted / highMl - 1e-9), most: Math.ceil(mlWanted / lowMl - 1e-9) };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runWebbedPlate(values) {
  const titerValue = parseNumber(values.titer);
  const pfu = parseNumber(values.pfu);
  const volume = parseNumber(values.volume);
  const plates = parseNumber(values.plates);
  if (!Number.isFinite(titerValue) || titerValue <= 0) return { ok: false, error: "Enter the lysate's titer in pfu/ml, greater than 0." };
  if (!Number.isFinite(pfu) || pfu <= 0) return { ok: false, error: "Enter the pfu wanted on each plate, greater than 0." };
  if (!Number.isFinite(volume) || volume <= 0) return { ok: false, error: "Enter the volume plated on each plate, in µl, greater than 0." };
  if (!Number.isFinite(plates) || plates < 1 || !Number.isInteger(plates) || plates > 100) {
    return { ok: false, error: "Enter the number of plates as a whole number from 1 to 100." };
  }
  const lysateUl = lysatePerPlate({ titerPfuPerMl: titerValue, pfuPerPlate: pfu });
  const neededUl = plates * volume;
  const plate = [
    `Lysate per plate: ${formatNumber(pfu)} / ${formatScientific(titerValue)} pfu/ml x 1,000 µl/ml = ${formatNumber(lysateUl)} µl.`,
  ];
  /** @type {string[]} */
  const notes = [];
  let result;
  const targetPfuPerMl = (pfu / volume) * 1000;
  if (targetPfuPerMl >= titerValue) {
    plate.push(`That is more than ${formatNumber(volume)} µl, so plate undiluted lysate: ${formatNumber(lysateUl)} µl on each plate, ${formatNumber(lysateUl * plates)} µl for ${plates} plates.`);
    result = `${formatNumber(lysateUl)} µl of undiluted lysate per plate`;
    if (lysateUl > LAB.maxLysateUl) {
      notes.push(`${formatNumber(lysateUl)} µl is over the lab's limit of ${LAB.maxLysateUl} µl on 250 µl of host (10% of the cell volume), which lyses the cells. Plate ${LAB.maxLysateUl} µl, or use a lysate with a higher titer.`);
    }
  } else {
    plate.push(`To plate that in ${formatNumber(volume)} µl, the tube must hold ${formatNumber(pfu)} pfu / ${formatNumber(volume)} µl x 1,000 = ${formatScientific(targetPfuPerMl)} pfu/ml.`);
    const plan = planDilution({ startPfuPerMl: titerValue, targetPfuPerMl, transferUl: LAB.transferUl, neededUl });
    plate.push(...planLines(plan, titerValue, targetPfuPerMl));
    plate.push(`Enough of the last tube: ${plates} plates x ${formatNumber(volume)} µl = ${formatNumber(neededUl)} µl.`);
    const last = must(plan.steps.at(-1));
    result = `${formatNumber(volume)} µl of tube ${last.tube} (${formatNumber(volume * (last.pfuPerMl / 1000))} pfu) on each of ${plates} plates`;
  }
  const { lowMl, highMl } = floodYield({ plates });
  const flood = [
    `Flooded with ${LAB.floodMl} ml of phage buffer each, a plate returns about ${LAB.yieldLowMl} to ${LAB.yieldHighMl} ml.`,
    `${plates} plates x ${LAB.yieldLowMl} to ${LAB.yieldHighMl} ml = ${formatNumber(lowMl)} to ${formatNumber(highMl)} ml of lysate.`,
  ];
  return {
    ok: true,
    sections: [
      { heading: "Webbed plates", steps: plate, result, notes },
      {
        heading: "Lysate from flooding",
        steps: flood,
        result: `About ${formatNumber(lowMl)} to ${formatNumber(highMl)} ml`,
        notes: ["Dry or aged plates return less; one returned only 3.5 ml of an 8 ml flood."],
      },
    ],
  };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runFlood(values) {
  const ml = parseNumber(values.ml);
  if (!Number.isFinite(ml) || ml <= 0 || ml > 10000) return { ok: false, error: "Enter the lysate wanted in ml, greater than 0." };
  const { fewest, most } = platesForLysate({ mlWanted: ml });
  const range = fewest === most ? `${most}` : `${fewest} to ${most}`;
  return {
    ok: true,
    sections: [
      {
        heading: "Plates to flood",
        steps: [
          `At ${LAB.yieldHighMl} ml per plate: ${formatNumber(ml)} / ${LAB.yieldHighMl} = ${formatNumber(ml / LAB.yieldHighMl)}, so ${fewest} ${fewest === 1 ? "plate" : "plates"}.`,
          `At ${LAB.yieldLowMl} ml per plate: ${formatNumber(ml)} / ${LAB.yieldLowMl} = ${formatNumber(ml / LAB.yieldLowMl)}, so ${most} ${most === 1 ? "plate" : "plates"}.`,
        ],
        result: `${range} webbed plates`,
        notes: ["Pour a plate or two more than this: some plates do not web or yield less."],
      },
    ],
  };
}

/* ---------------------------------------------------------------- MOI */

/**
 * MOI = pfu added / cells, with pfu = titer (pfu/ml) x µl added / 1,000 µl/ml and cells = cells/ml x µl
 * of culture / 1,000 µl/ml. `infected` is the share of cells that receive at least one phage when phages
 * land at random (Poisson): 1 - exp(-MOI). The site gives no OD-to-cells conversion, so cells are counted.
 *
 * @param {{ titerPfuPerMl: number, phageUl: number, cellsPerMl: number, hostUl: number }} input
 */
export function moi({ titerPfuPerMl, phageUl, cellsPerMl, hostUl }) {
  const pfu = (titerPfuPerMl * phageUl) / 1000;
  const cells = (cellsPerMl * hostUl) / 1000;
  const ratio = pfu / cells;
  return { pfu, cells, moi: ratio, infected: -Math.expm1(-ratio) };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runMoi(values) {
  const titerValue = parseNumber(values.titer);
  const phageUl = parseNumber(values.phage);
  const cellsPerMl = parseNumber(values.cells);
  const hostUl = parseNumber(values.host);
  if (!Number.isFinite(titerValue) || titerValue <= 0) return { ok: false, error: "Enter the phage titer in pfu/ml, greater than 0." };
  if (!Number.isFinite(phageUl) || phageUl <= 0) return { ok: false, error: "Enter the volume of phage added, in µl, greater than 0." };
  if (!Number.isFinite(cellsPerMl) || cellsPerMl <= 0) return { ok: false, error: "Enter the host cells per ml, greater than 0." };
  if (!Number.isFinite(hostUl) || hostUl <= 0) return { ok: false, error: "Enter the volume of host culture, in µl, greater than 0." };
  const result = moi({ titerPfuPerMl: titerValue, phageUl, cellsPerMl, hostUl });
  return {
    ok: true,
    sections: [
      {
        heading: "MOI",
        steps: [
          `pfu added: ${formatScientific(titerValue)} pfu/ml x ${formatNumber(phageUl)} µl / 1,000 µl/ml = ${formatNumber(result.pfu)} pfu.`,
          `Cells: ${formatScientific(cellsPerMl)} cells/ml x ${formatNumber(hostUl)} µl / 1,000 µl/ml = ${formatNumber(result.cells)} cells.`,
          `MOI: ${formatNumber(result.pfu)} pfu / ${formatNumber(result.cells)} cells = ${formatNumber(result.moi)}.`,
          `Cells that get at least one phage: 1 - exp(-${formatNumber(result.moi)}) = ${formatNumber(result.infected)}, about ${formatNumber(result.infected * 100)}%.`,
        ],
        result: `${formatNumber(result.moi)} pfu per cell`,
        notes: [
          "The last step assumes phages meet cells at random and every pfu adsorbs. Slow or incomplete adsorption infects fewer cells than it says.",
        ],
      },
    ],
  };
}

/* ---------------------------------------------------------------- EOP */

/**
 * EOP = titer on the test host / titer on the reference host.
 *
 * @param {{ testPfuPerMl: number, referencePfuPerMl: number }} input
 */
export function eop({ testPfuPerMl, referencePfuPerMl }) {
  return testPfuPerMl / referencePfuPerMl;
}

/**
 * The EOP steps shared by both EOP calculators. `boundPfuPerMl`, when the test host had no plaques, is
 * the titer one plaque on that plate would have meant, so the note can say how low the EOP is.
 *
 * @param {number} test @param {number} reference @param {number} [boundPfuPerMl]
 */
function eopSection(test, reference, boundPfuPerMl) {
  const ratio = eop({ testPfuPerMl: test, referencePfuPerMl: reference });
  /** @type {string[]} */
  const notes = [];
  if (test === 0) {
    const bound = boundPfuPerMl === undefined ? "" : ` It is below ${formatNumber(eop({ testPfuPerMl: boundPfuPerMl, referencePfuPerMl: reference }))}, what one plaque on that plate would give.`;
    notes.push(`No plaques on the test host: the phage did not plate at this dilution, which is not the same as an EOP of exactly 0.${bound} Plate a less dilute sample to measure it.`);
  }
  return {
    heading: "Efficiency of plating",
    steps: [
      `EOP: ${formatScientific(test)} pfu/ml on the test host / ${formatScientific(reference)} pfu/ml on the reference host = ${formatNumber(ratio)}.`,
      `As a percentage of the reference titer: ${formatNumber(ratio)} x 100 = ${formatNumber(ratio * 100)}%.`,
    ],
    result: `${formatNumber(ratio)} (${formatNumber(ratio * 100)}% of the reference titer)`,
    notes,
  };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runEop(values) {
  const test = parseNumber(values.test);
  const reference = parseNumber(values.reference);
  if (!Number.isFinite(test) || test < 0) return { ok: false, error: "Enter the titer on the test host in pfu/ml, 0 or more." };
  if (!Number.isFinite(reference) || reference <= 0) return { ok: false, error: "Enter the titer on the reference host in pfu/ml, greater than 0." };
  return { ok: true, sections: [eopSection(test, reference)] };
}

/** One host's titer line for the EOP-from-counts steps. @param {string} host @param {{ plaques: number, volumeUl: number, n: number }} count @param {number} pfuPerMl */
function countLine(host, { plaques, volumeUl, n }, pfuPerMl) {
  const undo = n === 0 ? "" : ` x 10^${n}`;
  return `Titer on the ${host}: ${formatNumber(plaques)} / ${formatNumber(volumeUl)} µl x 1,000${undo} = ${formatScientific(pfuPerMl)} pfu/ml.`;
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runEopCounts(values) {
  const test = readCount(values.testPlaques, values.testVolume, values.testDilution, " on the test host");
  if (!test.ok) return test;
  const reference = readCount(values.refPlaques, values.refVolume, values.refDilution, " on the reference host");
  if (!reference.ok) return reference;
  if (reference.plaques === 0) {
    return { ok: false, error: "No plaques on the reference host, so there is no titer to divide by. Count a less dilute plate." };
  }
  const testTiter = titer({ plaques: test.plaques, volumeUl: test.volumeUl, dilutionExponent: test.n }).pfuPerMl;
  const refTiter = titer({ plaques: reference.plaques, volumeUl: reference.volumeUl, dilutionExponent: reference.n }).pfuPerMl;
  const bound = titer({ plaques: 1, volumeUl: test.volumeUl, dilutionExponent: test.n }).pfuPerMl;
  const section = eopSection(testTiter, refTiter, bound);
  return {
    ok: true,
    sections: [
      {
        ...section,
        steps: [countLine("test host", test, testTiter), countLine("reference host", reference, refTiter), ...section.steps],
      },
    ],
  };
}

/* ---------------------------------------------------------------- lysate volume */

/**
 * Lysate for a run of plates: (pfu per plate x plates) / titer (pfu/ml) x 1,000 µl/ml, the webbed
 * plate formula for all the plates at once.
 *
 * @param {{ titerPfuPerMl: number, pfuPerPlate: number, plates: number }} input
 */
export function lysateForPlates({ titerPfuPerMl, pfuPerPlate, plates }) {
  const totalPfu = pfuPerPlate * plates;
  const totalUl = lysatePerPlate({ titerPfuPerMl, pfuPerPlate: totalPfu });
  return { totalPfu, totalUl, perPlateUl: totalUl / plates };
}

/** @param {Record<string, string | undefined>} values @returns {ToolResult} */
function runLysateVolume(values) {
  const titerValue = parseNumber(values.titer);
  const pfu = parseNumber(values.pfu);
  const plates = parseNumber(values.plates);
  const volume = parseNumber(values.volume);
  if (!Number.isFinite(titerValue) || titerValue <= 0) return { ok: false, error: "Enter the lysate's titer in pfu/ml, greater than 0." };
  if (!Number.isFinite(pfu) || pfu <= 0) return { ok: false, error: "Enter the pfu wanted on each plate, greater than 0." };
  if (!Number.isFinite(plates) || plates < 1 || !Number.isInteger(plates) || plates > 100) {
    return { ok: false, error: "Enter the number of plates as a whole number from 1 to 100." };
  }
  if (!Number.isFinite(volume) || volume <= 0) return { ok: false, error: "Enter the volume plated on each plate, in µl, greater than 0." };
  const { totalPfu, totalUl, perPlateUl } = lysateForPlates({ titerPfuPerMl: titerValue, pfuPerPlate: pfu, plates });
  const steps = [
    `pfu for all plates: ${formatNumber(pfu)} x ${plates} = ${formatNumber(totalPfu)} pfu.`,
    `Lysate for all plates: ${formatNumber(totalPfu)} / ${formatScientific(titerValue)} pfu/ml x 1,000 µl/ml = ${formatNumber(totalUl)} µl.`,
    `Per plate: ${formatNumber(totalUl)} µl / ${plates} = ${formatNumber(perPlateUl)} µl.`,
  ];
  /** @type {string[]} */
  const notes = [];
  let result;
  if (perPlateUl >= volume * (1 - 1e-9)) {
    steps.push(`That is at least the ${formatNumber(volume)} µl plated per plate, so plate the lysate undiluted: ${formatNumber(perPlateUl)} µl on each plate.`);
    result = `${formatNumber(totalUl)} µl of undiluted lysate, ${formatNumber(perPlateUl)} µl on each of ${plates} plates`;
    if (perPlateUl > LAB.maxLysateUl) {
      notes.push(`${formatNumber(perPlateUl)} µl is over the lab's limit of ${LAB.maxLysateUl} µl on 250 µl of host (10% of the cell volume), which lyses the cells. Use a lysate with a higher titer.`);
    }
  } else {
    const mixUl = plates * volume;
    if (totalUl >= 1) {
      steps.push(
        `To plate ${formatNumber(volume)} µl on each: ${plates} plates x ${formatNumber(volume)} µl = ${formatNumber(mixUl)} µl, so mix ${formatNumber(totalUl)} µl lysate + ${formatNumber(mixUl - totalUl)} µl phage buffer.`,
      );
      result = `${formatNumber(totalUl)} µl of lysate in ${formatNumber(mixUl)} µl, ${formatNumber(volume)} µl on each of ${plates} plates`;
    } else {
      steps.push(`${formatNumber(totalUl)} µl is under 1 µl, too little to pipette, so dilute the lysate first and plate ${formatNumber(volume)} µl of the last tube on each plate.`);
      result = `${formatNumber(totalUl)} µl of lysate for ${plates} plates, made by dilution`;
      notes.push("The webbed plate calculator plans the dilution tubes for these numbers.");
    }
  }
  return { ok: true, sections: [{ heading: "Lysate needed", steps, result, notes }] };
}

/* ---------------------------------------------------------------- registry */

/**
 * @typedef {object} ToolDefinition
 * @property {string} path the page it is on
 * @property {string} title the form's accessible name
 * @property {ToolField[]} fields
 * @property {(values: Record<string, string | undefined>) => ToolResult} run
 */

/** @type {Record<string, ToolDefinition>} */
export const TOOLS = {
  titer: {
    path: "/research/tools/titer",
    title: "Titer calculator",
    fields: [
      { name: "plaques", label: "Plaques counted", value: "111", hint: "On one plate, or in one spot." },
      {
        name: "volume",
        label: "Volume plated or spotted",
        unit: "µl",
        value: String(LAB.ulPlated),
        hint: `The lab plates ${LAB.ulPlated} µl for a full plate titer and spots ${LAB.ulSpot} µl for a spot titer; enter 10 for a 10 µl spot.`,
        source: SOURCES.fullPlate,
      },
      { name: "dilution", label: "Dilution, 10 to the minus", value: "6", hint: "6 for the 10^-6 tube, 0 if undiluted." },
    ],
    run: runTiter,
  },
  dilution: {
    path: "/research/tools/dilution",
    title: "Serial dilution planner",
    fields: [
      { name: "start", label: "Starting titer", unit: "pfu/ml", value: "1.11e10", hint: "1.11e10 or 1.11 x 10^10." },
      { name: "target", label: "Target concentration", unit: "pfu/ml", value: "1.11e6" },
      {
        name: "transfer",
        label: "Volume carried into each tube",
        unit: "µl",
        value: String(LAB.transferUl),
        hint: "Each 10-fold tube gets 9 times this of phage buffer: 10 µl + 90 µl.",
        source: SOURCES.tenfold,
      },
      { name: "needed", label: "Volume needed from the last tube (optional)", unit: "µl", value: "", hint: "Plates x µl per plate. Earlier tubes are scaled up to supply it." },
    ],
    run: runDilution,
  },
  "webbed-plate": {
    path: "/research/tools/webbed-plate",
    title: "Webbed plate calculator",
    fields: [
      { name: "titer", label: "Lysate titer", unit: "pfu/ml", value: "1.11e10", hint: "1.11e10 or 1.11 x 10^10." },
      { name: "pfu", label: "pfu wanted per plate", value: "11100", hint: "What webs depends on plaque size; see the notes below." },
      { name: "volume", label: "Volume plated per plate", unit: "µl", value: String(LAB.ulPlated), source: SOURCES.fullPlate },
      { name: "plates", label: "Plates to pour", value: String(LAB.plates), source: SOURCES.yields },
    ],
    run: runWebbedPlate,
  },
  flood: {
    path: "/research/tools/webbed-plate",
    title: "Plates for a lysate volume",
    fields: [{ name: "ml", label: "Lysate wanted", unit: "ml", value: "20", hint: "10 ml to archive plus 10 ml for DNA extraction is 20 ml." }],
    run: runFlood,
  },
  moi: {
    path: "/research/tools/moi",
    title: "MOI calculator",
    fields: [
      { name: "titer", label: "Phage titer", unit: "pfu/ml", value: "1e9", hint: "1e9 or 1 x 10^9." },
      { name: "phage", label: "Phage volume added", unit: "µl", value: String(LAB.ulPlated), source: SOURCES.fullPlate },
      {
        name: "cells",
        label: "Host cells",
        unit: "cells/ml",
        value: "1e8",
        hint: "Counted, not read off an OD: the site gives no OD-to-cells factor for the lab's hosts. 1e8 is only the worked example's number.",
      },
      { name: "host", label: "Host culture volume", unit: "µl", value: "250", source: SOURCES.fullPlate },
    ],
    run: runMoi,
  },
  eop: {
    path: "/research/tools/eop",
    title: "EOP from titers",
    fields: [
      { name: "test", label: "Titer on the test host", unit: "pfu/ml", value: "2e8", hint: "2e8 or 2 x 10^8." },
      { name: "reference", label: "Titer on the reference host", unit: "pfu/ml", value: "1e10", hint: "Usually the host the phage was isolated on." },
    ],
    run: runEop,
  },
  "eop-counts": {
    path: "/research/tools/eop",
    title: "EOP from plaque counts",
    fields: [
      { name: "testPlaques", label: "Plaques on the test host", value: "20" },
      { name: "testVolume", label: "Volume plated on the test host", unit: "µl", value: String(LAB.ulPlated), source: SOURCES.fullPlate },
      { name: "testDilution", label: "Test host dilution, 10 to the minus", value: "5", hint: "5 for the 10^-5 tube, 0 if undiluted." },
      { name: "refPlaques", label: "Plaques on the reference host", value: "100" },
      { name: "refVolume", label: "Volume plated on the reference host", unit: "µl", value: String(LAB.ulPlated), source: SOURCES.fullPlate },
      { name: "refDilution", label: "Reference host dilution, 10 to the minus", value: "6", hint: "6 for the 10^-6 tube, 0 if undiluted." },
    ],
    run: runEopCounts,
  },
  "lysate-volume": {
    path: "/research/tools/lysate-volume",
    title: "Lysate volume planner",
    fields: [
      { name: "titer", label: "Lysate titer", unit: "pfu/ml", value: "1e7", hint: "1e7 or 1 x 10^7." },
      { name: "pfu", label: "pfu wanted per plate", value: "10000", hint: "What webs depends on plaque size and host; see the notes below." },
      { name: "plates", label: "Plates to pour", value: String(LAB.plates), source: SOURCES.yields },
      { name: "volume", label: "Volume plated per plate", unit: "µl", value: String(LAB.ulPlated), source: SOURCES.fullPlate },
    ],
    run: runLysateVolume,
  },
};

/** The calculators on a page, in page order. @param {string} path */
export function toolsOnPage(path) {
  return Object.keys(TOOLS).filter((id) => TOOLS[id]?.path === path);
}

/**
 * A tool's values: the query string's where it has them, the field's opening value where not.
 *
 * @param {string} id
 * @param {URLSearchParams} [params]
 * @returns {Record<string, string>}
 */
export function toolValues(id, params) {
  const tool = TOOLS[id];
  if (!tool) throw new Error(`No calculator named ${id}.`);
  /** @type {Record<string, string>} */
  const values = {};
  for (const field of tool.fields) {
    const given = params?.get(field.name);
    values[field.name] = given === null || given === undefined ? field.value : given.slice(0, 40);
  }
  return values;
}

/** @param {string} id @param {Record<string, string | undefined>} values @returns {ToolResult} */
export function runTool(id, values) {
  const tool = TOOLS[id];
  if (!tool) throw new Error(`No calculator named ${id}.`);
  return tool.run(values);
}

/* ---------------------------------------------------------------- view */

/**
 * @typedef {{ tag: "div" | "h3" | "ol" | "li" | "p" | "strong" | "sup", className?: string, children: Array<ViewNode | string> }} ViewNode
 */

/** @param {string} line @returns {Array<ViewNode | string>} */
function lineNodes(line) {
  return textParts(line).map((part) => (part.sup ? { tag: "sup", children: [part.text] } : part.text));
}

/**
 * What a result looks like, as plain nodes, so the server component and the browser module build the
 * same markup from one description and neither parses HTML. `summary` is the one line per section the
 * status region announces; `detail` is the worked steps under it.
 *
 * @param {ToolResult} result
 * @returns {{ summary: Array<ViewNode | string>, detail: ViewNode[] }}
 */
export function resultView(result) {
  if (!result.ok) {
    return { summary: [{ tag: "p", className: "phage-tool-error", children: [result.error] }], detail: [] };
  }
  const summary = result.sections
    .filter((section) => section.result)
    .map((section) => ({
      tag: /** @type {const} */ ("p"),
      className: "phage-tool-answer",
      children: [`${section.heading}: `, { tag: /** @type {const} */ ("strong"), children: lineNodes(section.result ?? "") }],
    }));
  const detail = result.sections.map((section) => ({
    tag: /** @type {const} */ ("div"),
    className: "phage-tool-section",
    children: [
      { tag: /** @type {const} */ ("h3"), children: [section.heading] },
      {
        tag: /** @type {const} */ ("ol"),
        className: "phage-tool-steps",
        children: section.steps.map((step) => ({ tag: /** @type {const} */ ("li"), children: lineNodes(step) })),
      },
      ...(section.notes ?? []).map((note) => ({
        tag: /** @type {const} */ ("p"),
        className: "phage-tool-note",
        children: lineNodes(note),
      })),
    ],
  }));
  return { summary, detail };
}

